def dehydrate_timedelta(value):
    """ Dehydrator for `timedelta` values.

    :param value:
    :type value: timedelta
    :return:
    """
    if value is None:
        return None
    if hasattr(value, "total_seconds"):
        return value.total_seconds()
    raise TypeError(f"Expected a timedelta-like object, got {type(value).__name__}")

def dehydrate_time(value):
    """ Dehydrator for `time` values.

    :param value:
    :type value: Time
    :return:
    """
    if value is None:
        return None
    # Try ISO format if available
    try:
        return value.isoformat()
    except AttributeError:
        pass
    # Try to build a dictionary representation if the object has time attributes
    try:
        if hasattr(value, 'hour') and hasattr(value, 'minute') and hasattr(value, 'second'):
            result = {
                'hour': getattr(value, 'hour'),
                'minute': getattr(value, 'minute'),
                'second': getattr(value, 'second')
            }
            if hasattr(value, 'microsecond'):
                result['microsecond'] = getattr(value, 'microsecond')
            if hasattr(value, 'tzinfo') and value.tzinfo is not None:
                result['tzinfo'] = str(value.tzinfo)
            return result
    except Exception:
        pass
    # Fallback to string representation
    try:
        return str(value)
    except Exception as e:
        raise ValueError("Cannot dehydrate time value") from e

def dehydrate_point(value):
    """Dehydrator for Point data.

    :param value: Point instance
    :type value: Point
    :return: A serialisable representation of the point (dict or tuple)
    """
    # Handle None explicitly
    if value is None:
        return None

    # If the object provides a to_dict() method, use it
    if hasattr(value, "to_dict") and callable(value.to_dict):
        try:
            return value.to_dict()
        except Exception as exc:
            raise ValueError(f"Error calling to_dict on Point: {exc}") from exc

    # If the object provides a to_tuple() method, use it
    if hasattr(value, "to_tuple") and callable(value.to_tuple):
        try:
            return value.to_tuple()
        except Exception as exc:
            raise ValueError(f"Error calling to_tuple on Point: {exc}") from exc

    # Fallback: try to extract common coordinate attributes
    try:
        coords = {}
        for attr in ("x", "y", "z"):
            if hasattr(value, attr):
                coords[attr] = getattr(value, attr)
        if not coords:
            raise ValueError("Point object has no coordinate attributes")
        return coords
    except Exception as exc:
        raise ValueError(f"Unable to dehydrate Point: {exc}") from exc

def keys(self):
    """ Return the keys of the record.

    :return: list of key names
    """
    # Try to return the keys of the instance's attribute dictionary.
    try:
        return list(self.__dict__.keys())
    except AttributeError:
        # Fallback: if the object behaves like a mapping, use super()
        try:
            return list(super().keys())
        except Exception:
            raise TypeError("Object does not support key retrieval")

def index(self, key):
    """ Return the index of the given item.

    :param key: a key
    :return: index
    :rtype: int
    """
    # Determine the underlying container
    container = None
    if hasattr(self, 'data'):
        container = self.data
    elif hasattr(self, '_data'):
        container = self._data
    else:
        raise AttributeError("No data container found in object")

    # If container is a dict, use its keys
    if isinstance(container, dict):
        try:
            return list(container.keys()).index(key)
        except ValueError:
            raise ValueError(f"{key!r} is not a key in the container")

    # If container is a sequence (list, tuple, etc.)
    try:
        return container.index(key)
    except AttributeError:
        raise TypeError("Container does not support indexing")
    except ValueError:
        raise ValueError(f"{key!r} is not in the container")

def values(self, *keys):
    """Return the values of the record, optionally filtering to
    include only certain values by index or key.

    :param keys: indexes or keys of the items to include; if none
                 are provided, all values will be included
    :return: list of values
    :rtype: list
    """
    # Attempt to obtain a list of (key, value) pairs
    try:
        items = list(self.items())
    except AttributeError:
        # Fallback: assume the object itself is iterable of (key, value) tuples
        items = list(self)

    # If no keys specified, return all values
    if not keys:
        return [v for _, v in items]

    # Otherwise filter based on provided keys or indices
    result = []
    for key in keys:
        if isinstance(key, int):
            # Treat as index into the items list
            try:
                result.append(items[key][1])
            except IndexError:
                # Ignore out-of-range indices
                continue
        else:
            # Treat as a key; find the first matching entry
            for k, v in items:
                if k == key:
                    result.append(v)
                    break
    return result

def data(self, *keys):
    """ Return the keys and values of this record as a dictionary,
    optionally including only certain values by index or key. Keys
    provided in the items that are not in the record will be
    inserted with a value of :const:`None`; indexes provided
    that are out of bounds will trigger an :exc:`IndexError`.

    :param keys: indexes or keys of the items to include; if none
                  are provided, all values will be included
    :return: dictionary of values, keyed by field name
    :raises: :exc:`IndexError` if an out-of-bounds index is specified
    """
    # Attempt to obtain the underlying list of items
    try:
        items = self.items
    except AttributeError:
        try:
            items = self._items
        except AttributeError:
            # Fallback: iterate over self if it yields items
            items = list(self)

    # Helper to extract key/value from an item
    def _extract(item):
        if isinstance(item, tuple) and len(item) == 2:
            return item[0], item[1]
        if hasattr(item, "key") and hasattr(item, "value"):
            return getattr(item, "key"), getattr(item, "value")
        # If item is a dict with a single key/value pair
        if isinstance(item, dict) and len(item) == 1:
            k = next(iter(item))
            return k, item[k]
        return None, None

    # If no keys specified, return all items
    if not keys:
        result = {}
        for item in items:
            k, v = _extract(item)
            if k is not None:
                result[k] = v
        return result

    # Otherwise, process each key/index
    result = {}
    for key in keys:
        if isinstance(key, int):
            # Index-based lookup
            if key < 0 or key >= len(items):
                raise IndexError(f"Index {key} out of bounds")
            item = items[key]
            k, v = _extract(item)
            if k is not None:
                result[k] = v
        else:
            # Key-based lookup
            found = False
            for item in items:
                k, v = _extract(item)
                if k == key:
                    result[k] = v
                    found = True
                    break
            if not found:
                result[key] = None
    return result

def pop_u16(self):
    """Remove the last two bytes of data, returning them as a big-endian 16‑bit unsigned integer."""
    # Ensure the object has a 'data' attribute
    if not hasattr(self, 'data'):
        raise AttributeError("The object has no 'data' attribute")

    data = self.data

    # Validate that data is a bytes-like object
    if not isinstance(data, (bytes, bytearray, memoryview)):
        raise TypeError(f"Unsupported data type {type(data).__name__} for pop_u16")

    # Ensure there are at least two bytes to pop
    if len(data) < 2:
        raise ValueError("Not enough data to pop 2 bytes")

    # Extract the last two bytes
    if isinstance(data, memoryview):
        last_two = data[-2:].tobytes()
    else:
        last_two = data[-2:]

    # Remove the last two bytes from the data
    if isinstance(data, bytearray):
        del data[-2:]
    else:
        # For immutable types (bytes, memoryview) reassign a new slice
        if isinstance(data, memoryview):
            # Convert to bytes to avoid keeping a memoryview slice
            self.data = data.tobytes()[:-2]
        else:
            self.data = data[:-2]

    # Convert the extracted bytes to an integer (big-endian)
    return int.from_bytes(last_two, 'big')

def point_type(name, fields, srid_map):
    """ Dynamically create a Point subclass. """
    # Validate the name
    if not isinstance(name, str):
        raise TypeError("name must be a string")

    # Validate and process fields
    if isinstance(fields, dict):
        field_names = list(fields.keys())
        defaults = fields
    elif isinstance(fields, (list, tuple)):
        field_names = list(fields)
        defaults = {}
    else:
        raise TypeError("fields must be a list or a dict")

    # Validate srid_map
    if not isinstance(srid_map, dict):
        raise TypeError("srid_map must be a dict")

    # Ensure field names are unique
    if len(set(field_names)) != len(field_names):
        raise ValueError("duplicate field names in fields")

    # Build the class dictionary
    class_dict = {}

    # Use __slots__ to restrict attributes to the given fields
    class_dict['__slots__'] = field_names

    # Store the srid_map as a class attribute
    class_dict['srid_map'] = srid_map

    # Define __init__ to accept positional and keyword arguments
    def __init__(self, *args, **kwargs):
        if len(args) > len(field_names):
            raise TypeError(f"expected at most {len(field_names)} positional arguments, got {len(args)}")
        # Assign positional arguments
        for name_, value in zip(field_names, args):
            setattr(self, name_, value)
        # Assign remaining fields from kwargs or defaults
        for name_ in field_names[len(args):]:
            if name_ in kwargs:
                setattr(self, name_, kwargs.pop(name_))
            elif name_ in defaults:
                setattr(self, name_, defaults[name_])
            else:
                raise TypeError(f"missing required argument: {name_}")
        if kwargs:
            raise TypeError(f"unexpected keyword arguments: {', '.join(kwargs.keys())}")

    class_dict['__init__'] = __init__

    # Define a helpful __repr__
    def __repr__(self):
        parts = [f"{name_}={getattr(self, name_)!r}" for name_ in field_names]
        return f"{name}({', '.join(parts)})"

    class_dict['__repr__'] = __repr__

    # Optionally, define __eq__ for value comparison
    def __eq__(self, other):
        if not isinstance(other, self.__class__):
            return NotImplemented
        return all(getattr(self, n) == getattr(other, n) for n in field_names)

    class_dict['__eq__'] = __eq__

    # Create and return the new subclass
    return type(name, (object,), class_dict)

def deprecated(message):
    """ Decorator for deprecating functions and methods.

    ::

        @deprecated("'foo' has been deprecated in favour of 'bar'")
        def foo(x):
            pass

    """
    import warnings
    import functools
    if not isinstance(message, str):
        raise TypeError("message must be a string")
    def decorator(func):
        if not callable(func):
            raise TypeError("decorated object must be callable")
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            warnings.warn(message, DeprecationWarning, stacklevel=2)
            return func(*args, **kwargs)
        return wrapper
    return decorator

def parse_version(s: str) -> tuple[int, ...]:
    """poor man's version comparison"""
    if not isinstance(s, str):
        raise TypeError(f"Expected str, got {type(s).__name__}")
    s = s.strip()
    if not s:
        return ()
    parts = s.split('.')
    nums = []
    for part in parts:
        # extract leading digits from each part
        num_str = ''
        for ch in part:
            if ch.isdigit():
                num_str += ch
            else:
                break
        if num_str:
            nums.append(int(num_str))
    return tuple(nums)

def setdefault(self, key, default=None):
    """D.setdefault(k[,d]) -> D.get(k,d), also set D[k]=d if k not in D"""
    if key in self:
        return self[key]
    else:
        self[key] = default
        return default

def get(self, key, default=None):
    """D.get(k[,d]) -> D[k] if k in D, else d.  d defaults to None."""
    try:
        return self[key]
    except KeyError:
        return default

