@classmethod
def _reset_logging(cls):
    """
    Reset
    """
    import logging
    try:
        # Shut down all existing logging handlers
        logging.shutdown()
        # Reconfigure the root logger with default settings
        logging.basicConfig(level=logging.WARNING)
    except Exception as e:
        raise RuntimeError(f"Failed to reset logging: {e}") from e

def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    if not isinstance(classes, (list, tuple)):
        raise TypeError("classes must be a list or tuple of types")
    result = []
    seen = set()
    for c in classes:
        if not isinstance(c, type):
            raise TypeError(f"Expected a type, got {type(c).__name__}")
        if c in seen:
            continue
        # Determine if c is redundant (i.e., a subclass of any other class in the list)
        redundant = False
        for other in classes:
            if other is c:
                continue
            if issubclass(c, other):
                redundant = True
                break
        if not redundant:
            result.append(c)
            seen.add(c)
    return result

def namesAndDescriptions(self, all=False):  # pylint:disable=redefined-builtin
    """Return attribute names and descriptions defined by interface."""
    if not isinstance(all, bool):
        raise TypeError("Parameter 'all' must be a boolean value.")
    result = {}
    # Determine which classes to inspect: the class itself or its entire MRO
    classes_to_inspect = [self.__class__] if not all else self.__class__.__mro__
    for cls in classes_to_inspect:
        for name, value in cls.__dict__.items():
            # Skip private/internal attributes and methods
            if name.startswith('_') or callable(value):
                continue
            # Attempt to retrieve a description; many interface attributes are
            # instances of a custom Attribute class that expose a 'description'
            # attribute. If not present, skip the attribute.
            desc = getattr(value, 'description', None)
            if desc is not None:
                # If a subclass overrides an attribute, its description should win.
                if name not in result:
                    result[name] = desc
    return result

def names(self, all=False):  # pylint:disable=redefined-builtin
    """Return the attribute names defined by the interface."""
    # Validate the `all` argument
    if not isinstance(all, bool):
        raise TypeError(f"'all' must be a bool, got {type(all).__name__}")

    # Prefer a class-defined INTERFACE attribute if present
    interface = getattr(self.__class__, "INTERFACE", None)
    if interface is not None:
        # Ensure we have a list of names
        try:
            names = list(interface)
        except TypeError:
            raise TypeError("INTERFACE must be an iterable of attribute names")
        if all:
            # Include inherited interface definitions
            for base in self.__class__.__mro__[1:]:
                base_interface = getattr(base, "INTERFACE", None)
                if base_interface:
                    try:
                        names.extend(base_interface)
                    except TypeError:
                        raise TypeError("INTERFACE must be an iterable of attribute names")
            # Remove duplicates while preserving order
            seen = set()
            names = [n for n in names if not (n in seen or seen.add(n))]
        return names

    # Fallback: introspect class attributes (excluding methods and private names)
    names = []
    mro = self.__class__.__mro__
    # If all is False, only consider the most derived class
    classes_to_inspect = mro if all else (mro[0],)
    for cls in classes_to_inspect:
        if cls is object:
            continue
        for name, value in cls.__dict__.items():
            if name.startswith("_"):
                continue
            if callable(value):
                continue
            if name not in names:
                names.append(name)
    return names

def _c_optimizations_ignored():
    """
    The opposite of `_c_optimizations_required`.
    """
    return not _c_optimizations_required()

def reset(self):
    """Reset the histogram.

    Current context is reset to an empty dict.
    Bins are reinitialized with the *initial_value*
    or with *make_bins()* (depending on the initialization).
    """
    # Reset the context
    self.context = {}

    # Reinitialize bins
    if hasattr(self, 'initial_value') and self.initial_value is not None:
        # If bins already exist, try to preserve their structure
        if hasattr(self, 'bins'):
            # Preserve list/tuple structure
            if isinstance(self.bins, (list, tuple)):
                self.bins = [self.initial_value] * len(self.bins)
            # Preserve dict structure
            elif isinstance(self.bins, dict):
                for key in self.bins:
                    self.bins[key] = self.initial_value
            else:
                # Fallback: replace bins entirely
                self.bins = self.initial_value
        else:
            # No existing bins attribute; just set it
            self.bins = self.initial_value
    else:
        # Use make_bins() to create new bins
        if hasattr(self, 'make_bins') and callable(self.make_bins):
            self.bins = self.make_bins()
        else:
            raise AttributeError("Histogram has no method 'make_bins' to reinitialize bins")

def integral(bins, edges):
    """Compute integral (scale for a histogram).

    *bins* contain values, and *edges* form the mesh
    for the integration.
    Their format is defined in :class:`.histogram` description.
    """
    # Basic validation
    if bins is None or edges is None:
        raise TypeError("Both 'bins' and 'edges' must be provided")
    try:
        bins = list(bins)
        edges = list(edges)
    except TypeError:
        raise TypeError("'bins' and 'edges' must be iterable")

    if len(edges) < 2:
        raise ValueError("'edges' must contain at least two values")
    if len(bins) != len(edges) - 1:
        raise ValueError("Number of bins must be one less than number of edges")

    # Compute bin widths and validate edges
    widths = []
    for i in range(len(edges) - 1):
        try:
            w = edges[i + 1] - edges[i]
        except Exception as exc:
            raise TypeError("All elements of 'edges' must be numeric") from exc
        if w < 0:
            raise ValueError("Edges must be monotonically increasing")
        widths.append(w)

    # Compute the integral as sum(bins * widths)
    total = 0.0
    for b, w in zip(bins, widths):
        try:
            total += float(b) * w
        except Exception as exc:
            raise TypeError("All elements of 'bins' must be numeric") from exc

    return total

def is_fill_request_seq(seq):
    """Test whether *seq* can be converted to a FillRequestSeq.

    True only if it is a FillRequest element
    or contains at least one such,
    and it is not a Source sequence.
    """
    try:
        # If seq is a FillRequest element
        if isinstance(seq, FillRequest):
            return True
        # If seq is a Source element
        if isinstance(seq, Source):
            return False
        # If seq is iterable
        try:
            iterator = iter(seq)
        except TypeError:
            return False
        for item in iterator:
            if isinstance(item, FillRequest):
                return True
        return False
    except Exception:
        return False

