def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    # Basic validation of the input
    if not hasattr(app, "spec"):
        raise ValueError("The provided application object does not have a 'spec' attribute.")
    if not hasattr(app.spec, "manifest"):
        raise ValueError("The application spec does not contain a 'manifest' attribute.")
    if not isinstance(app.spec.manifest, (list, tuple)):
        raise TypeError("app.spec.manifest should be a list or tuple of resource definitions.")

    # Ensure the observer_schema attribute exists and is a dictionary
    if not hasattr(app.spec, "observer_schema") or app.spec.observer_schema is None:
        app.spec.observer_schema = {}
    if not isinstance(app.spec.observer_schema, dict):
        # If it's not a dict, try to convert it or raise an error
        try:
            app.spec.observer_schema = dict(app.spec.observer_schema)
        except Exception as exc:
            raise TypeError("app.spec.observer_schema must be a dictionary.") from exc

    # Helper to create a unique key for each resource
    def _resource_key(resource):
        kind = resource.get("kind")
        metadata = resource.get("metadata", {})
        name = metadata.get("name")
        if not kind or not name:
            return None
        return f"{kind}/{name}"

    # Iterate over each resource in the manifest
    for resource in app.spec.manifest:
        if not isinstance(resource, dict):
            # Skip non-dict entries
            continue
        key = _resource_key(resource)
        if not key:
            # Skip resources that don't have a proper kind/name
            continue

        # Skip if a custom observer schema is already defined for this resource
        if key in app.spec.observer_schema:
            continue

        # Build a simple default observer schema
        metadata = resource.get("metadata", {})
        default_schema = {
            "metadata": {
                "name": metadata.get("name"),
                "namespace": metadata.get("namespace", "default"),
            },
            "status": {},
        }

        # Store the default schema
        app.spec.observer_schema[key] = default_schema

    # Return the updated observer_schema for convenience
    return app.spec.observer_schema

def status_str(self, prefix=''):
    """Return string of validator status, with optional prefix."""
    # Retrieve the status attribute if it exists
    status = getattr(self, 'status', None)

    # If there is no status or it is empty, return an empty string
    if not status:
        return ''

    # Convert the status to a readable string
    if isinstance(status, (list, tuple)):
        # Handle lists/tuples of messages or tuples of (severity, message)
        parts = []
        for item in status:
            if isinstance(item, tuple):
                parts.append(' '.join(map(str, item)))
            else:
                parts.append(str(item))
        status_text = ', '.join(parts)
    elif isinstance(status, dict):
        # Handle dicts mapping severity to messages
        status_text = ', '.join(f'{k}: {v}' for k, v in status.items())
    else:
        # Fallback for any other type
        status_text = str(status)

    # Prepend the optional prefix if provided
    if prefix:
        return f'{prefix}{status_text}'
    return status_text

def status_str(self, prefix=''):
    """Return string representation of validation log, with optional prefix."""
    # Validate prefix
    if prefix is None:
        prefix = ''
    if not isinstance(prefix, str):
        raise TypeError(f"prefix must be a string, got {type(prefix).__name__}")

    # Retrieve the validation log; it may be stored under different names
    log = getattr(self, 'validation_log', None)
    if log is None:
        log = getattr(self, '_validation_log', None)

    # If still None or not iterable, return empty string
    if log is None:
        return ''
    try:
        iterator = iter(log)
    except TypeError:
        # Not iterable; try to convert to string directly
        return f"{prefix}{str(log)}"

    # Build the string representation
    lines = []
    for entry in iterator:
        # If entry is a tuple or list, format nicely
        if isinstance(entry, (tuple, list)):
            # Convert each element to string and join with ': '
            formatted = ': '.join(str(e) for e in entry)
        else:
            formatted = str(entry)
        lines.append(f"{prefix}{formatted}")

    return '\n'.join(lines)

def validate(self, inventory, extract_spec_version=False):
    """Validate a given inventory.

    If extract_spec_version is True then will look at the type value to determine
    the specification version. In the case that there is no type value or it isn't
    valid, then other tests will be based on the version given in self.spec_version.
    """
    import re

    # Basic type check
    if not isinstance(inventory, dict):
        raise ValueError("Inventory must be a dictionary.")

    # Determine the specification version to use for validation
    spec_version = self.spec_version
    if extract_spec_version:
        type_val = inventory.get('type')
        if isinstance(type_val, str):
            # Attempt to extract a version number from the type string
            m = re.search(r'(\d+(?:\.\d+)*)', type_val)
            if m:
                spec_version = m.group(1)
    else:
        # When not extracting, the inventory must provide its own spec_version
        if 'spec_version' not in inventory:
            raise ValueError("Missing 'spec_version' in inventory.")
        spec_version = inventory['spec_version']

    # Validate the spec_version format
    if not isinstance(spec_version, str) or not re.match(r'^\d+(\.\d+)?$', spec_version):
        raise ValueError(f"Invalid specification version: {spec_version}")

    # Required keys in the inventory
    required_keys = ['type', 'items']
    for key in required_keys:
        if key not in inventory:
            raise ValueError(f"Missing required key '{key}' in inventory.")

    # Validate the 'type' field
    if not isinstance(inventory['type'], str) or not inventory['type']:
        raise ValueError("The 'type' field must be a non-empty string.")

    # Validate the 'items' field
    items = inventory['items']
    if not isinstance(items, list):
        raise ValueError("The 'items' field must be a list.")
    for idx, item in enumerate(items):
        if not isinstance(item, dict):
            raise ValueError(f"Item at index {idx} is not a dictionary.")
        # Example sub‑validation: each item should have an 'id' and a 'name'
        if 'id' not in item or 'name' not in item:
            raise ValueError(f"Item at index {idx} missing required 'id' or 'name' fields.")

    # If all checks pass, return True
    return True

def check_digests_present_and_used(self, manifest_files, digests_used):
    """Check all digests in manifest that are needed are present and used."""
    # Validate inputs
    if manifest_files is None:
        raise ValueError("manifest_files cannot be None")
    if digests_used is None:
        raise ValueError("digests_used cannot be None")

    if not isinstance(manifest_files, dict):
        raise TypeError("manifest_files must be a dict mapping digest to file information")
    if not isinstance(digests_used, (set, list, tuple)):
        raise TypeError("digests_used must be a set, list, or tuple of digests")

    # Normalise digests_used to a set for efficient lookup
    digests_used_set = set(digests_used)

    # Digests that are used but not present in the manifest
    missing_in_manifest = digests_used_set - set(manifest_files.keys())
    if missing_in_manifest:
        raise ValueError(
            f"Digests used but not present in manifest: {sorted(missing_in_manifest)}"
        )

    # Digests that are present in the manifest but not used
    unused_in_manifest = set(manifest_files.keys()) - digests_used_set
    if unused_in_manifest:
        raise ValueError(
            f"Digests present in manifest but not used: {sorted(unused_in_manifest)}"
        )

    # All checks passed
    return True

def validate_as_prior_version(self, prior):
    """Check that prior is a valid prior version of the current inventory object.

    The input variable prior is also expected to be an InventoryValidator object
    and both self and prior inventories are assumed to have been checked for
    internal consistency.
    """
    # Ensure InventoryValidator class is available
    try:
        InventoryValidator
    except NameError:
        raise TypeError("InventoryValidator class is not defined in the current context")

    # Type check for prior
    if not isinstance(prior, InventoryValidator):
        raise TypeError("prior must be an instance of InventoryValidator")

    # Retrieve and validate version attributes
    try:
        self_version = getattr(self, "version", None)
        prior_version = getattr(prior, "version", None)
    except Exception as exc:
        raise ValueError("Failed to access version attributes") from exc

    if self_version is None or prior_version is None:
        raise ValueError("Both inventories must have a 'version' attribute")

    # Compare versions; prior must be strictly older
    try:
        if prior_version >= self_version:
            raise ValueError(
                f"Prior version ({prior_version}) must be older than current version ({self_version})"
            )
    except TypeError as exc:
        raise ValueError("Version attributes must be comparable (e.g., int, float, or str)") from exc

    # Retrieve and validate inventory collections
    try:
        self_inv = getattr(self, "inventory", None)
        prior_inv = getattr(prior, "inventory", None)
    except Exception as exc:
        raise ValueError("Failed to access inventory attributes") from exc

    if self_inv is None or prior_inv is None:
        raise ValueError("Both inventories must have an 'inventory' attribute")

    # Ensure inventories are iterable
    if not hasattr(self_inv, "__iter__") or not hasattr(prior_inv, "__iter__"):
        raise ValueError("Inventory attributes must be iterable collections")

    # Check that every item in the prior inventory exists in the current inventory
    if isinstance(prior_inv, dict):
        missing_keys = [k for k in prior_inv if k not in self_inv]
        if missing_keys:
            raise ValueError(
                f"Current inventory is missing items from prior: {missing_keys}"
            )
    else:
        # Assume list, set, or other iterable of items
        missing_items = [item for item in prior_inv if item not in self_inv]
        if missing_items:
            raise ValueError(
                f"Current inventory is missing items from prior: {missing_items}"
            )

    # All checks passed
    return True

def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    # Basic validation
    if inventory is None:
        raise ValueError("inventory cannot be None")
    if not isinstance(version, (int, float)):
        raise TypeError("version must be a number")
    # Normalise inventory to a dict of logical_path -> dict of version -> content_file
    if isinstance(inventory, list):
        # Expect list of dicts with keys 'logical_path', 'version', 'content_file'
        temp = {}
        for entry in inventory:
            try:
                lp = entry['logical_path']
                v = entry['version']
                cf = entry['content_file']
            except (KeyError, TypeError):
                continue
            if lp not in temp:
                temp[lp] = {}
            temp[lp][v] = cf
        inventory = temp
    elif isinstance(inventory, dict):
        # Convert any list of tuples to dict
        for lp, vmap in list(inventory.items()):
            if isinstance(vmap, list):
                new_map = {}
                for item in vmap:
                    if isinstance(item, (list, tuple)) and len(item) == 2:
                        new_map[item[0]] = item[1]
                inventory[lp] = new_map
    else:
        raise TypeError("inventory must be a dict or list")

    result = {}
    for logical_path, version_map in inventory.items():
        if not isinstance(version_map, dict):
            continue
        files = set()
        for v, content_file in version_map.items():
            try:
                if v >= version and content_file is not None:
                    files.add(content_file)
            except TypeError:
                # Skip entries where comparison fails
                continue
        if files:
            result[logical_path] = files
    return result

def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    # Basic type checks
    if fixity is None:
        raise ValueError("Fixity block cannot be None")
    if manifest_files is None:
        raise ValueError("Manifest files list cannot be None")

    if not isinstance(manifest_files, (set, list, tuple, frozenset)):
        raise TypeError("manifest_files must be an iterable of file names")

    # Ensure all manifest file names are strings
    for f in manifest_files:
        if not isinstance(f, str):
            raise TypeError(f"Manifest file name {f!r} is not a string")

    # Helper to validate a single fixity entry
    def _validate_entry(entry, file_name):
        if not isinstance(entry, dict):
            raise ValueError(f"Fixity entry for file '{file_name}' must be a dict")
        required_keys = {"hash", "algorithm"}
        missing = required_keys - entry.keys()
        if missing:
            raise ValueError(f"Fixity entry for file '{file_name}' missing keys: {missing}")
        if not isinstance(entry["hash"], str):
            raise ValueError(f"Hash for file '{file_name}' must be a string")
        if not isinstance(entry["algorithm"], str):
            raise ValueError(f"Algorithm for file '{file_name}' must be a string")

    # Validate based on the type of fixity
    if isinstance(fixity, dict):
        # Keys are file names, values are entry dicts
        for file_name, entry in fixity.items():
            if not isinstance(file_name, str):
                raise ValueError(f"File name key {file_name!r} is not a string")
            if file_name not in manifest_files:
                raise ValueError(f"File '{file_name}' in fixity block not found in manifest")
            _validate_entry(entry, file_name)
    elif isinstance(fixity, (list, tuple)):
        seen_files = set()
        for entry in fixity:
            if not isinstance(entry, dict):
                raise ValueError("Each fixity entry must be a dict")
            if "file" not in entry:
                raise ValueError("Fixity entry missing 'file' key")
            file_name = entry["file"]
            if not isinstance(file_name, str):
                raise ValueError(f"File name {file_name!r} in entry is not a string")
            if file_name in seen_files:
                raise ValueError(f"Duplicate fixity entry for file '{file_name}'")
            seen_files.add(file_name)
            if file_name not in manifest_files:
                raise ValueError(f"File '{file_name}' in fixity block not found in manifest")
            _validate_entry(entry, file_name)
    else:
        raise TypeError("Fixity block must be a dict or a list/tuple of entries")

    # All checks passed
    return True

def files_list(path):
    """
    Return the files in `path`
    """
    import os
    if not isinstance(path, (str, bytes, os.PathLike)):
        raise TypeError("path must be a string or path-like object")
    try:
        if not os.path.exists(path):
            raise FileNotFoundError(f"Path does not exist: {path}")
        if not os.path.isdir(path):
            raise NotADirectoryError(f"Path is not a directory: {path}")
        entries = os.listdir(path)
        files = [entry for entry in entries if os.path.isfile(os.path.join(path, entry))]
        return sorted(files)
    except PermissionError as e:
        raise PermissionError(f"Permission denied accessing {path}") from e

def _explore_zipfile(zip_path):
    """
    Get packages' data from zip_path

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    zip_path : str
        zip file path

    Returns
    -------
    dict
        Mapping from XML basename to a dictionary of file names and their binary data.
    """
    import os
    import zipfile

    if not isinstance(zip_path, str) or not zip_path:
        raise ValueError("zip_path must be a non-empty string")

    if not os.path.isfile(zip_path):
        raise FileNotFoundError(f"Zip file not found: {zip_path}")

    try:
        with zipfile.ZipFile(zip_path, 'r') as zf:
            # Identify all XML files to determine basenames to group
            xml_basenames = set()
            for name in zf.namelist():
                if name.endswith('/') or name.endswith('\\'):
                    continue  # skip directories
                if name.lower().endswith('.xml'):
                    base = os.path.splitext(os.path.basename(name))[0]
                    xml_basenames.add(base)

            # Prepare groups dictionary
            groups = {base: {} for base in xml_basenames}

            # Populate groups with all files that share the same basename
            for name in zf.namelist():
                if name.endswith('/') or name.endswith('\\'):
                    continue
                base = os.path.splitext(os.path.basename(name))[0]
                if base in groups:
                    try:
                        data = zf.read(name)
                    except RuntimeError as e:
                        # If reading fails, skip this file but log the error
                        data = None
                    groups[base][name] = data

            # Remove empty groups (in case no files matched a basename)
            groups = {k: v for k, v in groups.items() if v}

            return groups

    except zipfile.BadZipFile as e:
        raise ValueError(f"Invalid zip file: {zip_path}") from e
    except Exception as e:
        raise RuntimeError(f"Error processing zip file {zip_path}") from e

def fix_namespace_prefix_w(content):
