def match_pubdate(node, pubdate_xpaths):
    """
    Retorna o primeiro match da lista de pubdate_xpaths
    """
    if node is None:
        return None
    if not pubdate_xpaths:
        return None

    # Ensure we have an iterable of xpaths
    if isinstance(pubdate_xpaths, str):
        xpaths = [pubdate_xpaths]
    else:
        try:
            iter(pubdate_xpaths)
            xpaths = pubdate_xpaths
        except TypeError:
            xpaths = [pubdate_xpaths]

    for xpath in xpaths:
        try:
            matches = node.xpath(xpath)
            if matches:
                return matches[0]
        except Exception:
            # Skip invalid xpath expressions or evaluation errors
            continue

    return None

def pretty(self, indent=0, debug=False):
    """Return a pretty formatted representation of self."""
    if not isinstance(indent, int) or indent < 0:
        raise ValueError("indent must be a non‑negative integer")
    if not isinstance(debug, bool):
        raise ValueError("debug must be a boolean")

    indent_str = '  ' * indent
    parts = [f"{indent_str}{self.__class__.__name__}"]

    # Include id if present
    if hasattr(self, "id") and self.id is not None:
        parts.append(f"(id={self.id})")

    # Include other attributes (skip id, children, doc)
    attrs = []
    try:
        attrs_dict = vars(self)
    except TypeError:
        attrs_dict = {}
    for key, value in attrs_dict.items():
        if key in ("id", "children", "doc"):
            continue
        attrs.append(f"{key}={value!r}")
    if attrs:
        parts.append(f"[{', '.join(attrs)}]")

    line = " ".join(parts)
    if debug:
        line += f" @ {hex(id(self))}"

    # Gather child representations
    child_lines = []
    children = None
    try:
        children = getattr(self, "children")
    except AttributeError:
        pass
    if children is None:
        try:
            children = list(self)
        except TypeError:
            children = []

    for child in children:
        if child is None:
            continue
        try:
            child_repr = child.pretty(indent + 1, debug) if hasattr(child, "pretty") else str(child)
        except Exception:
            child_repr = str(child)
        child_lines.append(child_repr)

    if child_lines:
        return line + "\n" + "\n".join(child_lines)
    return line

def get_versions():
    """Get version information or return default if unable to do so."""
    try:
        try:
            from importlib.metadata import version, PackageNotFoundError
        except ImportError:
            from importlib_metadata import version, PackageNotFoundError
        pkg = __package__ or __name__
        ver = version(pkg)
        return {"version": ver}
    except Exception:
        return {"version": "0.0.0"}

def render(pieces, style):
    """Render the given version pieces into the requested style."""
    # Validate inputs
    if pieces is None:
        raise ValueError("pieces cannot be None")
    if not isinstance(style, str):
        raise TypeError("style must be a string")
    # Ensure pieces is iterable
    try:
        iterator = iter(pieces)
    except TypeError:
        raise TypeError("pieces must be an iterable of renderable objects")

    rendered_parts = []
    for piece in iterator:
        try:
            # If the piece has a render method, use it
            if hasattr(piece, "render") and callable(piece.render):
                rendered = piece.render(style)
            else:
                # Fallback to string conversion
                rendered = str(piece)
        except Exception:
            # If rendering fails, fall back to string representation
            rendered = str(piece)
        rendered_parts.append(rendered)

    return "".join(rendered_parts)

def plus_or_dot(pieces):
    """Return a + if we don't already have one, else return a ."""
    try:
        return '.' if '+' in pieces else '+'
    except TypeError:
        raise TypeError("pieces must be an iterable (e.g., list or string) containing '+' or not")

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    import subprocess
    import os
    import shlex
    import sys

    # Build the command list
    if isinstance(commands, str):
        cmd = shlex.split(commands)
    else:
        cmd = list(commands)

    if args:
        if isinstance(args, str):
            cmd += shlex.split(args)
        else:
            cmd += list(args)

    if verbose:
        print(f"Running command: {' '.join(cmd)}")

    # Merge environment variables
    env_dict = os.environ.copy()
    if env:
        env_dict.update(env)

    try:
        result = subprocess.run(
            cmd,
            cwd=cwd,
            env=env_dict,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            text=True,
            check=True
        )
        if verbose:
            print(result.stdout)
        if not hide_stderr and result.stderr:
            print(result.stderr, file=sys.stderr)
        return result
    except subprocess.CalledProcessError as e:
        if verbose:
            print(e.stdout)
            if not hide_stderr:
                print(e.stderr, file=sys.stderr)
        raise

def register_vcs_handler(vcs, method):
    """Create decorator to mark a method as the handler of a VCS."""
    if not isinstance(vcs, str) or not vcs:
        raise ValueError("vcs must be a non-empty string")
    if not callable(method):
        raise TypeError("method must be callable")
    if not hasattr(register_vcs_handler, "_registry"):
        register_vcs_handler._registry = {}
    register_vcs_handler._registry[vcs] = method
    return method

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    num_objects = 0
    good_objects = 0

    # Attempt to obtain an iterable of objects from the root
    objects = None
    for attr in ('objects', 'children', 'elements'):
        if hasattr(self, attr):
            objects = getattr(self, attr)
            break

    if objects is None:
        try:
            objects = iter(self)
        except Exception:
            objects = []

    # If the attribute is a dict, iterate over its values
    if isinstance(objects, dict):
        objects = objects.values()

    # Ensure we have an iterable
    try:
        iterator = iter(objects)
    except TypeError:
        if show_warnings:
            print(f"Warning: {self} does not contain iterable objects for validation.")
        return 0, 0

    for obj in iterator:
        num_objects += 1
        valid = True

        if validate_objects:
            try:
                if hasattr(obj, 'validate') and callable(obj.validate):
                    obj.validate()
            except Exception as e:
                valid = False
                if show_warnings:
                    print(f"Warning: object {obj} failed validation: {e}")

        if check_digests:
            try:
                if hasattr(obj, 'check_digest') and callable(obj.check_digest):
                    obj.check_digest()
            except Exception as e:
                valid = False
                if show_warnings:
                    print(f"Warning: object {obj} failed digest check: {e}")

        if valid:
            good_objects += 1

    return num_objects, good_objects

def initialize(self):
    """Create and initialize a new OCFL storage root."""
    # Ensure the instance has a root_path attribute
    if not hasattr(self, 'root_path'):
        raise AttributeError("Instance missing 'root_path' attribute.")
    root = self.root_path

    # Validate the root path type
    if not isinstance(root, str):
        raise TypeError(f"root_path must be a string, got {type(root).__name__}")

    # Check if the root already exists
    if os.path.exists(root):
        if os.path.isdir(root):
            raise FileExistsError(f"OCFL root already exists at '{root}'.")
        else:
            raise FileExistsError(f"A non-directory file already exists at '{root}'.")

    try:
        # Create the root directory
        os.makedirs(root, exist_ok=False)

        # Create the objects directory
        objects_dir = os.path.join(root, 'objects')
        os.makedirs(objects_dir, exist_ok=False)

        # Create the .ocfl_root file with the required version
        ocfl_root_file = os.path.join(root, '.ocfl_root')
        with open(ocfl_root_file, 'w', encoding='utf-8') as f:
            f.write('ocfl_version: 1.0\n')

        # Mark the instance as initialized
        self.initialized = True

    except OSError as exc:
        # Clean up partially created structure if an error occurs
        try:
            if os.path.isdir(root):
                # Remove any created directories/files
                for dirpath, dirnames, filenames in os.walk(root, topdown=False):
                    for filename in filenames:
                        os.remove(os.path.join(dirpath, filename))
                    for dirname in dirnames:
                        os.rmdir(os.path.join(dirpath, dirname))
                os.rmdir(root)
        except Exception:
            pass  # Ignore cleanup errors

        raise RuntimeError(f"Failed to initialize OCFL root at '{root}': {exc}") from exc

def next_version(version):
    """Next version identifier following existing pattern.

    Must deal with both zero-prefixed and non-zero prefixed versions.
    """
    if not isinstance(version, str):
        raise TypeError(f"Expected string, got {type(version).__name__}")
    if not version:
        raise ValueError("Empty version string")
    if not version.isdigit():
        raise ValueError(f"Invalid version format: {version!r}")
    # Determine if leading zeros should be preserved
    preserve_zeros = len(version) > 1 and version[0] == '0'
    new_num = int(version) + 1
    if preserve_zeros:
        return f"{new_num:0{len(version)}d}"
    return str(new_num)

def validate_version_inventories(self, version_dirs):
    """Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    # Basic validation of input
    if not isinstance(version_dirs, (list, tuple)):
        raise TypeError("version_dirs must be a list or tuple of directory names")
    if not version_dirs:
        return

    # Ensure required attributes exist
    if not hasattr(self, "root_inventory") or not isinstance(self.root_inventory, dict):
        raise AttributeError("Instance must have a 'root_inventory' dict attribute")
    if not hasattr(self, "digests_diff"):
        self.digests_diff = {}

    import os
    import xml.etree.ElementTree as ET

    for vdir in version_dirs:
        # Build path to inventory file
        inv_path = os.path.join(vdir, "inventory.xml")
        if not os.path.isfile(inv_path):
            raise FileNotFoundError(f"Inventory file not found in version directory '{vdir}'")

        # Parse the inventory XML
        try:
            tree = ET.parse(inv_path)
            root = tree.getroot()
        except ET.ParseError as e:
            raise ValueError(f"Failed to parse inventory in '{vdir}': {e}")

        # Iterate over items in the inventory
        for item in root.findall(".//item"):
            item_id = item.get("id")
            digest = item.get("digest")
            if item_id is None or digest is None:
                continue  # skip malformed entries

            # Compare with root inventory digest
            root_digest = self.root_inventory.get(item_id)
            if root_digest is None:
                # Item not present in root inventory; skip or record as needed
                continue

            if digest != root_digest:
                # Record differing digests
                self.digests_diff.setdefault(vdir, {})[item_id] = (root_digest, digest)

    # No explicit return value; state is stored in self.digests_diff and validated inventories.

def amend_bzparams(self, params, bug_ids):
    """Amend the Bugzilla params"""
    if not isinstance(params, dict):
        raise TypeError("params must be a dict")
    if bug_ids is None:
        return
    # Convert bug_ids to a list of string ids
    if isinstance(bug_ids, str):
        # Split comma-separated string, strip whitespace
        bug_ids = [b.strip() for b in bug_ids.split(',') if b.strip()]
    elif isinstance(bug_ids, (list, tuple, set)):
        bug_ids = list(bug_ids)
    else:
        # Try to iterate; if not iterable, treat as single id
        try:
            bug_ids = list(bug_ids)
        except TypeError:
            bug_ids = [bug_ids]
    # Ensure all ids are strings and strip whitespace
    bug_ids = [str(b).strip() for b in bug_ids if str(b).strip()]
    if not bug_ids:
        return
    # Merge with existing 'ids' param if present
    existing = params.get('ids')
    if existing:
        if isinstance(existing, str):
            existing_ids = [e.strip() for e in existing.split(',') if e.strip()]
        else:
            existing_ids = [str(e).strip() for e in existing if str(e).strip()]
        # Combine and deduplicate while preserving order
        combined = []
        for id_ in existing_ids + bug_ids:
            if id_ not in combined:
                combined.append(id_)
    else:
        combined = bug_ids
    params['ids'] = ','.join(combined)

def parse_arguments(*arguments):
    '''
    Given command-line arguments with which this script was invoked, parse the arguments and return
    them as an ArgumentParser instance.
    '''
    # Attempt to create an ArgumentParser; raise a clear error if argparse is unavailable
    try:
        parser = argparse.ArgumentParser()
    except NameError as e:
        raise ImportError("argparse module is required") from e

    # Parse the provided arguments, handling common argparse errors gracefully
    try:
        parsed = parser.parse_args(arguments)
        return parsed
    except SystemExit as e:
        # argparse calls sys.exit() on parsing errors; convert to a ValueError for consistency
        raise ValueError("Argument parsing failed") from e
    except Exception as e:
        # Catch any other parsing-related exceptions and re-raise as ValueError
        raise ValueError("Error parsing arguments") from e

def parser_flags(parser):
    """
    Given an argparse.ArgumentParser instance, return its argument flags in a space-separated
    string.
    """
    # Basic validation
    if parser is None:
        raise TypeError("parser must not be None")
    # argparse.ArgumentParser instances expose a _actions attribute
    if not hasattr(parser, "_actions"):
        raise TypeError("Expected an argparse.ArgumentParser instance")
    flags = []
    for action in parser._actions:
        # action.option_strings is a list of option strings for this action
        option_strings = getattr(action, "option_strings", [])
        for opt in option_strings:
            if isinstance(opt, str) and opt.startswith("-"):
                flags.append(opt)
    return " ".join(flags)

def deep_merge_nodes(nodes):
    """
    Deep merge a list of (ScalarNode, value) tuples, merging duplicate keys.
    If a key appears multiple times, its values are merged recursively if they
    are MappingNodes; otherwise the last value wins.
    """
    # Helper to merge two nodes
    def _merge(a, b):
        # If both are MappingNodes, merge their mappings
        if isinstance(a, MappingNode) and isinstance(b, MappingNode):
            # Build dicts of key value to (ScalarNode, node)
            a_map = {k.value: (k, v) for k, v in a.value}
            b_map = {k.value: (k, v) for k, v in b.value}
            merged = []
            for key in set(a_map.keys()) | set(b_map.keys()):
                if key in a_map and key in b_map:
                    merged_val = _merge(a_map[key][1], b_map[key][1])
                elif key in a_map:
                    merged_val = a_map[key][1]
                else:
                    merged_val = b_map[key][1]
                merged.append((a_map.get(key, b_map[key])[0], merged_val))
            return MappingNode(tag=a.tag, value=merged)
        # If only one is a MappingNode, or neither, last wins
        return b

    if not isinstance(nodes, list):
        raise TypeError("nodes must be a list of tuples")
    merged_dict = {}
    for item in nodes:
        if not (isinstance(item, tuple) and len(item) == 2):
            raise ValueError("Each element must be a tuple of (ScalarNode, value)")
        key_node, val_node = item
        if not hasattr(key_node, "value"):
            raise ValueError("Key node must have a 'value' attribute")
        key = key_node.value
        if key in merged_dict:
            merged_dict[key] = _merge(merged_dict[key], val_node)
        else:
            merged_dict[key] = val_node
    # Preserve order of first occurrence
    result = []
    seen = set()
    for key_node, _ in nodes:
        key = key_node.value
        if key not in seen:
            seen.add(key)
            result.append((key_node, merged_dict[key]))
    return result

