    except Exception as exc:
        raise RuntimeError(f"Could not import borgmatic CLI: {exc}")

    # Try to obtain the click command object
    cmd = getattr(bm_main, "cli", None)
    if cmd is None:
        try:
            import click
            for attr in dir(bm_main):
                obj = getattr(bm_main, attr)
                if isinstance(obj, click.Command):
                    cmd = obj
                    break
        except Exception:
            pass

    if cmd is None:
        raise RuntimeError("Could not find a click.Command object in borgmatic.cli.main")

    # Generate the completion script
    try:
        import click
        if hasattr(click, "shell_completion"):
            from click.shell_completion import get_completion_script
            script = get_completion_script(cmd, "bash")
            return script
        else:
            raise RuntimeError("click does not support shell completion (missing click.shell_completion)")
    except Exception as exc:
        raise RuntimeError(f"Failed to generate completion script: {exc}")

