def paging(response, max_results):
    """Returns WAPI response page by page

    Args:
        response (list): WAPI response.
        max_results (int): Maximum number of objects to be returned in one page.
    Returns:
        Generator object with WAPI response split page by page.
    """
    # Validate max_results
    if not isinstance(max_results, int) or max_results <= 0:
        raise ValueError("max_results must be a positive integer")

    # Ensure response is a list (convert if iterable)
    if not isinstance(response, list):
        try:
            response = list(response)
        except TypeError:
            raise TypeError("response must be a list or an iterable that can be converted to a list")

    # Yield pages
    for start in range(0, len(response), max_results):
        yield response[start:start + max_results]

def _dictsum(dicts):
    """
    Combine values of the dictionaries supplied by iterable dicts.

    >>> _dictsum([{'a': 1, 'b': 2}, {'a': 5, 'b': 0}])
    {'a': 6, 'b': 2}
    """
    if dicts is None:
        raise TypeError("Expected an iterable of dictionaries, got None")
    result = {}
    for d in dicts:
        if not isinstance(d, dict):
            raise TypeError(f"Expected dict, got {type(d).__name__}")
        for key, value in d.items():
            if key in result:
                existing = result[key]
                # Ensure both values are numeric
                if not isinstance(existing, (int, float, complex)) or not isinstance(value, (int, float, complex)):
                    raise TypeError(f"Cannot sum non-numeric values for key '{key}': {existing!r} + {value!r}")
                result[key] = existing + value
            else:
                if not isinstance(value, (int, float, complex)):
                    raise TypeError(f"Non-numeric value for key '{key}': {value!r}")
                result[key] = value
    return result

def _replace_url_args(url, url_args):
    """Replace any custom string URL items with values in args"""
    if not isinstance(url, str):
        raise TypeError("url must be a string")
    if url_args is None:
        return url
    if not isinstance(url_args, dict):
        raise TypeError("url_args must be a dict")
    import re
    pattern = re.compile(r'\{([^}]+)\}')
    def repl(match):
        key = match.group(1)
        if key in url_args:
            return str(url_args[key])
        return match.group(0)
    try:
        return pattern.sub(repl, url)
    except Exception as exc:
        raise ValueError(f"Error replacing URL arguments: {exc}") from exc

def parser_flags(parser):
    """
    Given an argparse.ArgumentParser instance, return its argument flags in a space-separated
    string.
    """
    import argparse
    if not isinstance(parser, argparse.ArgumentParser):
        raise TypeError("parser must be an argparse.ArgumentParser instance")
    try:
        flags = []
        for action in parser._actions:
            # action.option_strings is a list of option strings (e.g., ['-h', '--help'])
            if hasattr(action, "option_strings"):
                flags.extend(action.option_strings)
        # Remove duplicates while preserving order
        seen = set()
        unique_flags = []
        for f in flags:
            if f not in seen:
                seen.add(f)
                unique_flags.append(f)
        return " ".join(unique_flags)
    except Exception as e:
        raise RuntimeError(f"Failed to extract flags from parser: {e}") from e

def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    if not isinstance(number, int):
        raise TypeError(f"number must be an int, got {type(number).__name__}")
    if number < 0:
        raise ValueError("number must be non-negative")
    if not isinstance(alphabet, list) or not alphabet:
        raise ValueError("alphabet must be a non-empty list")
    base = len(alphabet)
    if base <= 1:
        raise ValueError("alphabet must contain at least two symbols")
    if padding is not None:
        if not isinstance(padding, int) or padding < 0:
            raise ValueError("padding must be a non-negative integer or None")

    # Special case for zero
    if number == 0:
        result = [alphabet[0]]
    else:
        result = []
        n = number
        while n > 0:
            n, rem = divmod(n, base)
            result.append(alphabet[rem])
        result.reverse()

    # Apply padding if requested
    if padding is not None and len(result) < padding:
        pad_len = padding - len(result)
        result = [alphabet[0]] * pad_len + result

    return "".join(result)

def _replace_register(flow_params, register_number, register_value):
    """Replace value from flows to given register number

    'register_value' key in dictionary will be replaced by register number
    given by 'register_number'

    :param flow_params: Dictionary containing defined flows
    :param register_number: The number of register where value will be stored
    :param register_value: Key to be replaced by register number

    """
    # Basic type validation
    if not isinstance(flow_params, dict):
        raise TypeError("flow_params must be a dictionary")
    if not isinstance(register_number, int):
        raise TypeError("register_number must be an integer")
    if not isinstance(register_value, str):
        raise TypeError("register_value must be a string")

    # Iterate over the flows and replace the specified key's value
    for flow_name, flow in flow_params.items():
        # Handle a single flow dictionary
        if isinstance(flow, dict):
            if register_value in flow:
                flow[register_value] = register_number
        # Handle a list of flow dictionaries
        elif isinstance(flow, list):
            for item in flow:
                if isinstance(item, dict) and register_value in item:
                    item[register_value] = register_number
        # If the flow is neither dict nor list, skip it
        else:
            continue

    return flow_params

def replace_dots(value, arg):
    """Replaces all values of '.' to arg from the given string"""
    if not isinstance(value, str):
        raise TypeError("value must be a string")
    if not isinstance(arg, str):
        raise TypeError("arg must be a string")
    return value.replace('.', arg)

def subclasses(cls):
    """Return all subclasses of a class, recursively"""
    if not isinstance(cls, type):
        raise TypeError(f"Expected a class type, got {type(cls).__name__}")
    result = set()
    stack = [cls]
    while stack:
        current = stack.pop()
        for sub in current.__subclasses__():
            if sub not in result:
                result.add(sub)
                stack.append(sub)
    return list(result)

def string_to_int(string: str, alphabet: List[str]) -> int:
    """
    Convert a string to a number, using the given alphabet.

    The input is assumed to have the most significant digit first.
    """
    if not alphabet:
        raise ValueError("Alphabet must not be empty.")
    # Ensure alphabet has unique characters
    if len(set(alphabet)) != len(alphabet):
        raise ValueError("Alphabet contains duplicate characters.")
    base = len(alphabet)
    char_to_value = {ch: i for i, ch in enumerate(alphabet)}
    result = 0
    for ch in string:
        if ch not in char_to_value:
            raise ValueError(f"Character '{ch}' not in alphabet.")
        result = result * base + char_to_value[ch]
    return result

def unquote(name):
    """Remove quote from the given name."""
    if not isinstance(name, str):
        raise TypeError(f"Expected a string, got {type(name).__name__}")
    if len(name) >= 2 and name[0] == name[-1] and name[0] in ("'", '"'):
        return name[1:-1]
    return name

def split(s, platform='this'):
    """Multi-platform variant of shlex.split() for command-line splitting.
    For use with subprocess, for argv injection etc. Using fast REGEX.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """
    if s is None:
        raise TypeError("split() argument must be a string, not None")
    if not isinstance(s, str):
        s = str(s)

    # Determine platform
    if platform == 'this':
        import sys
        if sys.platform.startswith('win'):
            platform = 0
        else:
            platform = 1
    else:
        try:
            platform = int(platform)
        except Exception:
            raise ValueError("platform must be 'this', 1, or 0")

    if platform == 1:  # POSIX
        pattern = r'''(?:"([^"\\]*(?:\\.[^"\\]*)*)"|'([^'\\]*(?:\\.[^'\\]*)*)'|(\S+))'''
    elif platform == 0:  # Windows
        pattern = r'''(?:"((?:[^"\\]|\\.)*)"|(\S+))'''
    else:
        raise ValueError("Unsupported platform value: %r" % platform)

    regex = re.compile(pattern)
    args = []
    pos = 0
    length = len(s)
    while pos < length:
        # Skip leading whitespace
        while pos < length and s[pos].isspace():
            pos += 1
        if pos >= length:
            break
        m = regex.match(s, pos)
        if not m:
            # No match: treat the rest as a single argument
            args.append(s[pos:])
            break
        # Determine which group matched
        if m.group(1) is not None:
            token = m.group(1)
        elif m.group(2) is not None:
            token = m.group(2)
        else:
            token = m.group(3)
        # Unescape
        if platform == 1:
            token = token.replace(r'\\', '\\')
            token = token.replace(r'\"', '"')
            token = token.replace(r"\'", "'")
        else:
            token = token.replace(r'\\', '\\')
            token = token.replace(r'\"', '"')
        args.append(token)
        pos = m.end()
    return args

def addignored(ignored):
    """Use the git command to obtain the file names, turn it into a list, sort the list for only ignored files, return those files as a single string with each filename separated by a comma."""
    try:
        result = subprocess.run(
            ['git', 'ls-files', '--others', '--ignored', '--exclude-standard'],
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            text=True,
            check=True
        )
        files = [line.strip() for line in result.stdout.splitlines() if line.strip()]
        files.sort()
        return ','.join(files)
    except subprocess.CalledProcessError as e:
        raise RuntimeError(f"Git command failed: {e.stderr.strip()}")
    except OSError as e:
        raise RuntimeError(f"Git executable not found: {e}")
    except Exception as e:
        raise RuntimeError(f"Unexpected error: {e}")

def parse_frequency(frequency):
    """
    Given a frequency string with a number and a unit of time, return a corresponding
    datetime.timedelta instance or None if the frequency is None or "always".

    For instance, given "3 weeks", return datetime.timedelta(weeks=3)

    Raise ValueError if the given frequency cannot be parsed.
    """
    if frequency is None:
        return None
    if isinstance(frequency, str):
        freq_str = frequency.strip().lower()
        if freq_str == "always":
            return None
    else:
        raise ValueError(f"Frequency must be a string or None, got {type(frequency).__name__}")

    import re
    pattern = r'^\s*(\d+)\s*(\w+)\s*$'
    match = re.match(pattern, freq_str)
    if not match:
        raise ValueError(f"Unable to parse frequency: '{frequency}'")

    number_str, unit = match.groups()
    try:
        number = int(number_str)
    except ValueError:
        raise ValueError(f"Invalid number in frequency: '{number_str}'")

    unit_map = {
        'day': 'days',
        'days': 'days',
        'week': 'weeks',
        'weeks': 'weeks',
        'hour': 'hours',
        'hours': 'hours',
        'minute': 'minutes',
        'minutes': 'minutes',
        'second': 'seconds',
        'seconds': 'seconds',
    }

    if unit not in unit_map:
        raise ValueError(f"Unsupported time unit in frequency: '{unit}'")

    kwargs = {unit_map[unit]: number}
    return datetime.timedelta(**kwargs)

def is_local(host):
    """
    Checks if the host is the localhost

    :param host: The hostname or ip
    :return: True if the host is the localhost
    """
    if not isinstance(host, str) or not host:
        return False
    # Direct checks for common localhost names
    if host.lower() in ('localhost', 'localhost.localdomain'):
        return True
    try:
        # Resolve host to addresses
        infos = socket.getaddrinfo(host, None)
    except socket.gaierror:
        return False
    for family, _, _, _, sockaddr in infos:
        ip = sockaddr[0]
        if family == socket.AF_INET:
            # IPv4 loopback range 127.0.0.0/8
            if ip.startswith('127.'):
                return True
        elif family == socket.AF_INET6:
            # IPv6 loopback ::1
            if ip == '::1':
                return True
    return False

def write_configuration(config_filename, rendered_config, mode=0o600, overwrite=False):
    '''
    Given a target config filename and rendered config YAML, write it out to file. Create any
    containing directories as needed. But if the file already exists and overwrite is False,
    abort before writing anything.
    '''
    # Validate input types
    if not isinstance(config_filename, str) or not config_filename:
        raise TypeError("config_filename must be a non-empty string")
    if not isinstance(rendered_config, str):
        raise TypeError("rendered_config must be a string")
    if not isinstance(mode, int):
        raise TypeError("mode must be an integer")
    if not isinstance(overwrite, bool):
        raise TypeError("overwrite must be a boolean")

    # Ensure parent directories exist
    dirpath = os.path.dirname(config_filename)
    if dirpath:
        try:
            os.makedirs(dirpath, exist_ok=True)
        except OSError as e:
            raise OSError(f"Failed to create directories for {config_filename}: {e}") from e

    # Check for existing file
    if os.path.exists(config_filename) and not overwrite:
        raise FileExistsError(f"File {config_filename} already exists and overwrite is False")

    # Write the configuration file
    try:
        with open(config_filename, 'w', encoding='utf-8') as f:
            f.write(rendered_config)
        os.chmod(config_filename, mode)
    except OSError as e:
        raise OSError(f"Failed to write configuration to {config_filename}: {e}") from e
    return None

def oneline(script, seperator=" && "):
    """
    converts a script to one line command.
    THis is useful to run a single ssh command and pass a one line script.

    :param script:
    :return:
    """
    if script is None:
        return ""
    # Ensure separator is a string
    if seperator is None:
        seperator = ""
    else:
        seperator = str(seperator)

    # If script is a string, dedent and split into lines
    if isinstance(script, str):
        s = textwrap.dedent(script)
        lines = s.splitlines()
        parts = [line.strip() for line in lines if line.strip()]
    else:
        # Treat as an iterable of commands
        try:
            iter(script)
        except TypeError:
            parts = [str(script).strip()]
        else:
            parts = [str(item).strip() for item in script if item is not None]

    return seperator.join(parts)

def subprocess_run_helper(func, *args, timeout, extra_env=None):
    import subprocess, os, sys, importlib
    if not callable(func):
        raise TypeError("func must be callable")
    module_name = getattr(func, "__module__", None)
    if not module_name or module_name == "__main__":
        raise ValueError("func must be defined in an importable module")
    func_name = getattr(func, "__name__", None)
    if not func_name:
        raise ValueError("func must have a name")
    try:
        importlib.import_module(module_name)
    except Exception as exc:
        raise ImportError(f"Module '{module_name}' cannot be imported: {exc}") from exc
    script = f"import sys; import {module_name}; {module_name}.{func_name}(*sys.argv[1:])"
    cmd = [sys.executable, "-c", script] + [str(a) for a in args]
    env = os.environ.copy()
    if extra_env:
        env.update(extra_env)
    result = subprocess.run(cmd, timeout=timeout, env=env, capture_output=True, text=True)
    return result

def get_pattern(pattern, strip=True):
    """
    This method converts the given string to a regex pattern.
    """
    if not isinstance(pattern, str):
        raise TypeError("pattern must be a string")
    if strip:
        pattern = pattern.strip()
    # Escape all regex metacharacters to treat the string literally
    escaped = re.escape(pattern)
    try:
        return re.compile(escaped)
    except re.error as exc:
        raise ValueError(f"Failed to compile regex pattern: {exc}") from exc

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    # Validate input types
    if not isinstance(commands, (str, list)):
        raise TypeError(f"commands must be a str or list, got {type(commands).__name__}")
    if args is not None and not isinstance(args, list):
        raise TypeError(f"args must be a list or None, got {type(args).__name__}")
    if cwd is not None and not isinstance(cwd, str):
        raise TypeError(f"cwd must be a str or None, got {type(cwd).__name__}")
    if not isinstance(verbose, bool):
        raise TypeError(f"verbose must be a bool, got {type(verbose).__name__}")
    if not isinstance(hide_stderr, bool):
        raise TypeError(f"hide_stderr must be a bool, got {type(hide_stderr).__name__}")
    if env is not None and not isinstance(env, dict):
        raise TypeError(f"env must be a dict or None, got {type(env).__name__}")

    # Build the command list
    if isinstance(commands, str):
        cmd = [commands]
    else:
        # commands is a list
        cmd = list(commands)

    if args:
        cmd.extend(args)

    if verbose:
        print("Running command:", " ".join(cmd))

    try:
        result = subprocess.run(
            cmd,
            cwd=cwd,
            env=env,
            capture_output=True,
            text=True,
            check=True,
            stderr=subprocess.DEVNULL if hide_stderr else None
        )
        return result
    except FileNotFoundError as e:
        raise RuntimeError(f"Command not found: {commands}") from e
    except subprocess.CalledProcessError as e:
        # e.stderr may be None if hide_stderr is True
        err_msg = e.stderr if e.stderr is not None else ""
        raise RuntimeError(f"Command failed with return code {e.returncode}: {err_msg}") from e
    except Exception as e:
        raise RuntimeError(f"Error running command: {e}") from e

def is_ipv4(target):
    """ Test if IPv4 address or not
    """
    # If it's already an IPv4Address instance, return True
    if isinstance(target, ipaddress.IPv4Address):
        return True
    # If it's an IPv6Address instance, return False
    if isinstance(target, ipaddress.IPv6Address):
        return False
    try:
        addr = ipaddress.ip_address(target)
        return isinstance(addr, ipaddress.IPv4Address)
    except Exception:
        return False

def _dump_string(obj, dumper=None):
    """Dump to a py2-unicode or py3-string"""
    try:
        if dumper is None:
            # Use the safe dumper for general objects
            return yaml.safe_dump(obj, default_flow_style=False)
        else:
            # Use the provided dumper class
            return yaml.dump(obj, Dumper=dumper, default_flow_style=False)
    except yaml.YAMLError as exc:
        raise ValueError(f"Error dumping object to YAML string: {exc}") from exc

def gaussian(x):
    """Gaussian centered around 0.2 with a sigma of 0.1."""
    mu = 0.2
    sigma = 0.1
    try:
        x_arr = np.asarray(x)
    except Exception as e:
        raise ValueError("Input x must be a number or array-like") from e
    return np.exp(-((x_arr - mu) ** 2) / (2 * sigma ** 2))

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    """Load and validate configuration files.

    Parameters
    ----------
    config_filenames : sequence of str
        Filenames of configuration files to load.
    overrides : dict, optional
        Dictionary of key/value pairs to override in each configuration.
    resolve_env : bool, optional
        If True, environment variables in string values will be resolved.

    Returns
    -------
    tuple
        (config_dict, error_records)
        config_dict : dict
            Mapping of filename to parsed configuration dictionary.
        error_records : list of logging.LogRecord
            Log records for any parse errors encountered.
    """
    import logging
    import json
    import configparser
    import os
    import re

    # Ensure config_filenames is iterable
    if isinstance(config_filenames, (str, bytes)):
        config_filenames = [config_filenames]
    if not config_filenames:
        return {}, []

    config_dict = {}
    error_records = []

    def resolve_env_vars(obj):
        if isinstance(obj, dict):
            return {k: resolve_env_vars(v) for k, v in obj.items()}
        elif isinstance(obj, list):
            return [resolve_env_vars(v) for v in obj]
        elif isinstance(obj, str):
            # Replace ${VAR}
            def repl(match):
                var = match.group(1)
                return os.getenv(var, '')
            s = re.sub(r'\$\{([^}]+)\}', repl, obj)
            # Replace $VAR
            s = re.sub(r'\$([A-Za-z_][A-Za-z0-9_]*)', repl, s)
            return s
        else:
            return obj

    for filename in config_filenames:
        try:
            with open(filename, 'r') as f:
                content = f.read()
            # Try JSON
            try:
                config = json.loads(content)
            except json.JSONDecodeError:
                # Try INI via configparser
                parser = configparser.ConfigParser()
                with open(filename, 'r') as f2:
                    parser.read_file(f2)
                config = {section: dict(parser.items(section)) for section in parser.sections()}
            # Apply overrides
            if overrides is not None:
                if not isinstance(overrides, dict):
                    raise TypeError("overrides must be a dict")
                if isinstance(config, dict):
                    config.update(overrides)
            # Resolve environment variables
            if resolve_env:
                config = resolve_env_vars(config)
            config_dict[filename] = config
        except Exception as e:
            msg = f"Error loading configuration from {filename}: {e}"
            record = logging.LogRecord('config_loader', logging.ERROR, filename, 0, msg, None, None)
            error_records.append(record)

    return config_dict, error_records

def force_string(obj):
    """This function returns the bytes object corresponding to ``obj`` in case it is a string using UTF-8."""
    if isinstance(obj, str):
        try:
            return obj.encode('utf-8')
        except Exception as e:
            raise ValueError(f"Could not encode string to UTF-8: {e}") from e
    return obj

@classmethod
def protocol_handlers(cls, protocol_version=None):
    """ Return a dictionary of available Bolt protocol handlers,
        keyed by version tuple. If an explicit protocol version is
        provided, the dictionary will contain either zero or one items,
        depending on whether that version is supported. If no protocol
        version is provided, all available versions will be returned.

        :param protocol_version: tuple identifying a specific protocol
            version (e.g. (3, 5)) or None
        :return: dictionary of version tuple to handler class for all
            relevant and supported protocol versions
        :raise TypeError: if protocol version is not passed in a tuple
        """
    if protocol_version is not None and not isinstance(protocol_version, tuple):
        raise TypeError("protocol_version must be a tuple or None")
    handlers = getattr(cls, "_protocol_handlers", {})
    if protocol_version is None:
        return dict(handlers)
    handler = handlers.get(protocol_version)
    if handler is not None:
        return {protocol_version: handler}
    return {}

def from_raw_values(cls, values):
        """Create a Bookmarks object from a list of raw bookmark string values.

        You should not need to use this method unless you want to deserialize
        bookmarks.

        :param values: ASCII string values (raw bookmarks)
        :type values: Iterable[str]
        """
        if values is None:
            raise ValueError("values cannot be None")
        # Ensure values is iterable but not a string
        try:
            iterator = iter(values)
        except TypeError:
            raise TypeError("values must be an iterable of strings")
        if isinstance(values, (str, bytes)):
            raise TypeError("values must be an iterable of strings, not a single string")
        # Create an instance of the class
        obj = cls()
        for v in values:
            if not isinstance(v, str):
                raise TypeError(f"bookmark value must be a string, got {type(v).__name__}")
            # Skip empty strings
            if not v.strip():
                continue
            # Parse the raw string into name and page
            if ':' in v:
                name, page = v.split(':', 1)
            elif '=' in v:
                name, page = v.split('=', 1)
            else:
                name, page = v, None
            name = name.strip()
            page = page.strip() if page is not None else None
            # Try to convert page to int if possible
            if page is not None:
                try:
                    page = int(page)
                except ValueError:
                    pass
            # Create a Bookmark instance
            bookmark = Bookmark(name=name, page=page)
            # Add to the Bookmarks collection
            try:
                obj.append(bookmark)
            except AttributeError:
                obj.add(bookmark)
        return obj

def scale(self, other=None, recompute=False):
    """Compute or set scale (integral of the histogram).

    If *other* is ``None``, return scale of this histogram.
    If its scale was not computed before,
    it is computed and stored for subsequent use
    (unless explicitly asked to *recompute*).
    Note that after changing (filling) the histogram
    one must explicitly recompute the scale
    if it was computed before.

    If a float *other* is provided, rescale self to *other*.

    Histograms with scale equal to zero can't be rescaled.
    :exc:`.LenaValueError` is raised if one tries to do that.
    """
    # Helper to obtain the underlying count data
    def _get_counts():
        for attr in ('bins', 'data', 'values', 'counts'):
            if hasattr(self, attr):
                return getattr(self, attr)
        # Fallback: try to iterate over self
        try:
            return list(self)
        except Exception:
            raise AttributeError("Cannot compute scale: no data attribute found")

    # If no target scale is given, return (or compute) the current scale
    if other is None:
        # Compute if needed or if recompute requested
        if recompute or not hasattr(self, "_scale") or self._scale is None:
            counts = _get_counts()
            try:
                self._scale = sum(counts)
            except Exception as exc:
                raise AttributeError("Cannot compute scale: data is not summable") from exc
        return self._scale

    # Rescaling requested
    if not isinstance(other, (int, float)):
        raise TypeError("other must be a number")

    # Ensure current scale is known
    if not hasattr(self, "_scale") or self._scale is None:
        counts = _get_counts()
        try:
            current_scale = sum(counts)
        except Exception as exc:
            raise AttributeError("Cannot compute scale: data is not summable") from exc
        self._scale = current_scale
    else:
        current_scale = self._scale

    if current_scale == 0:
        raise LenaValueError("Cannot rescale histogram with zero scale")

    factor = other / current_scale

def scale(self, other=None):
        """Get or set the scale of the graph.

        If *other* is ``None``, return the scale of this graph.

        If a numeric *other* is provided, rescale to that value.
        If the graph has unknown or zero scale,
        rescaling that will raise :exc:`~.LenaValueError`.

        To get meaningful results, graph's fields are used.
        Only the last coordinate is rescaled.
        For example, if the graph has *x* and *y* coordinates,
        then *y* will be rescaled, and for a 3-dimensional graph
        *z* will be rescaled.
        All errors are rescaled together with their coordinate.
        """
        # Return current scale if no new value is requested
        if other is None:
            return getattr(self, "scale", None)

        # Validate that the new scale is numeric
        if not isinstance(other, (int, float)):
            raise TypeError(f"Scale must be a numeric value, got {type(other).__name__}")

        # Ensure the current scale is known and non-zero
        current_scale = getattr(self, "scale", None)
        if current_scale is None or current_scale == 0:
            raise LenaValueError("Cannot rescale graph with unknown or zero current scale")

        # Compute the scaling factor
        try:
            factor = other / current_scale
        except Exception as exc:
            raise LenaValueError(f"Error computing scaling factor: {exc}") from exc

        # Rescale all fields (only the last coordinate)
        fields = getattr(self, "fields", [])
        for field in fields:
            try:
                # Prefer a dedicated method for scaling the last coordinate
                if hasattr(field, "scale_last"):
                    field.scale_last(factor)
                elif hasattr(field, "scale"):
                    field.scale(factor)
                else:
                    # If no scaling method, skip silently
                    continue
            except Exception as exc:
                raise LenaValueError(f"Error scaling field {field}: {exc}") from exc

        # Rescale all errors associated with the graph
        errors = getattr(self, "errors", [])
        for err in errors:
            try:
                if hasattr(err, "scale_last"):
                    err.scale_last(factor)
                elif hasattr(err, "scale"):
                    err.scale(factor)
                else:
                    continue
            except Exception as exc:
                raise LenaValueError(f"Error scaling error {err}: {exc}") from exc

        # Update the graph's scale
        self.scale = other
        return None

def hist_to_graph(hist, make_value=None, get_coordinate="left",
                  field_names=("x", "y"), scale=None):
    """Convert a :class:`.histogram` to a :class:`.graph`.

    *make_value* is a function to set the value of a graph's point.
    By default it is bin content.
    *make_value* accepts a single value (bin content) without context.

    This option could be used to create graph's error bars.
    For example, to create a graph with errors
    from a histogram where bins contain
    a named tuple with fields *mean*, *mean_error* and a context
    one could use

    >>> make_value = lambda bin_: (bin_.mean, bin_.mean_error)

    *get_coordinate* defines what the coordinate
    of a graph point created from a histogram bin will be.
    It can be "left" (default), "right" and "middle".

    *field_names* set field names of the graph. Their number
    must be the same as the dimension of the result.
    For a *make_value* above they would be
    *("x", "y_mean", "y_mean_error")*.

    *scale* becomes the graph's scale (unknown by default).
    If it is ``True``, it uses the histogram scale.

    *hist* must contain only numeric bins (without context)
    or *make_value* must remove context when creating a numeric graph.

    Return the resulting graph.
    """
    # Validate get_coordinate
    if get_coordinate not in ("left", "right", "middle"):
        raise ValueError(f"get_coordinate must be 'left', 'right' or 'middle', got {get_coordinate!r}")

    # Default make_value: use bin content if available
    if make_value is None:
        def make_value(bin_):
            # Try common attributes for bin content
            for attr in ("content", "value", "mean"):
                if hasattr(bin_, attr):
                    return getattr(bin_, attr)
            # If bin_ itself is numeric, return it
            return bin_

    # Determine scale
    if scale is True:
        # Use histogram's scale if present
        scale = getattr(hist, "scale", None)
    # else keep provided scale (could be None)

    # Create graph object
    try:
        graph = Graph(scale=scale)
    except NameError:
        # Fallback: simple container if Graph is not defined
        class _Graph:
            def __init__(self, scale=None):
                self.scale = scale
                self.points = []

        graph = _Graph(scale=scale)

    # Prepare points list
    points = []

    # Iterate over histogram bins
    bins = getattr(hist, "bins", None)
    if bins is None:
        # Try to iterate directly over hist
        bins = hist

    for bin_ in bins:
        # Determine coordinate
        try:
            if get_coordinate == "left":
                coord = getattr(bin_, "left", None)
                if coord is None:
                    coord = getattr(bin_, "low", None)
                if coord is None:
                    edges = getattr(bin_, "edges", None)
                    if edges is not None and len(edges) >= 1:
                        coord = edges[0]
            elif get_coordinate == "right":
                coord = getattr(bin_, "right", None)
                if coord is None:
                    coord = getattr(bin_, "high", None)
                if coord is None:
                    edges = getattr(bin_, "edges", None)
                    if edges is not None and len(edges) >= 2:
                        coord = edges[1]
            else:  # middle
                left = getattr(bin_, "left", None)
                if left is None:
                    left = getattr(bin_, "low", None)
                right = getattr(bin_, "right", None)
                if right is None:
                    right = getattr(bin_, "high", None)
                if left is None or right is None:
                    edges = getattr(bin_, "edges", None)
                    if edges is not None and len(edges) >= 2:
                        left, right = edges[0], edges[1]
                if left is None or right is None:
                    raise ValueError("Cannot determine bin edges for middle coordinate")
                coord = (left + right) / 2.0
        except Exception as exc:
            raise ValueError(f"Error determining coordinate for bin {bin_!r}: {exc}") from exc

        # Compute value(s)
        val = make_value(bin_)
        # Ensure val is a tuple/list if multiple dimensions
        if isinstance(val, (tuple, list)):
            val_tuple = tuple(val)
        else:
            val_tuple = (val,)

        # Check field_names length
        if len(val_tuple) != len(field_names) - 1:
            raise ValueError(f"make_value returned {len(val_tuple)} values, "
                             f"but field_names expects {len(field_names)-1} values")

        # Build point tuple: (coord, *val_tuple)
        point = (coord,) + val_tuple
        points.append(point)

    # Attach points to graph
    if hasattr(graph, "points"):
        graph.points = points
    else:
        # If graph has method to add points
        try:
            for pt in points:
                graph.add_point(*pt)
        except Exception:
            # As a last resort, set attribute
            setattr(graph, "points", points)

    return graph

def verifyClass(iface, candidate, tentative=False):
    """Verify that the *candidate* might correctly provide *iface*."""
    try:
        # Validate interface
        if not isinstance(iface, type):
            raise TypeError(f"iface must be a class or type, got {type(iface).__name__}")

        # Validate candidate
        if candidate is None:
            raise TypeError("candidate cannot be None")

        # Helper to check attributes
        def _check_attrs(obj):
            for attr in dir(iface):
                if attr.startswith('_'):
                    continue
                if not hasattr(obj, attr):
                    raise TypeError(f"Candidate {obj} missing attribute {attr} required by interface {iface.__name__}")
                iface_attr = getattr(iface, attr)
                cand_attr = getattr(obj, attr)
                if callable(iface_attr) != callable(cand_attr):
                    raise TypeError(f"Attribute {attr} type mismatch between interface and candidate")

        # If candidate is a class
        if isinstance(candidate, type):
            if issubclass(candidate, iface):
                return True
            _check_attrs(candidate)
            return True

        # If candidate is an instance
        if isinstance(candidate, iface):
            return True
        _check_attrs(candidate)
        return True

    except Exception as exc:
        if tentative:
            return False
        raise

def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""
    # If an explicit metaclass is provided, use it after validation
    if explicit_mc is not None:
        if not isinstance(explicit_mc, type):
            raise TypeError(f"Explicit metaclass {explicit_mc!r} is not a class")
        return explicit_mc

    # No bases provided – default to the standard metaclass
    if not bases:
        return type

    # Collect the metaclasses of all base classes
    mcs = []
    for b in bases:
        if not isinstance(b, type):
            raise TypeError(f"Base {b!r} is not a class")
        mcs.append(type(b))

    # If all metaclasses are identical, return that one
    first_mc = mcs[0]
    if all(mc is first_mc for mc in mcs):
        return first_mc

    # Find the most derived metaclass (subclass of all others)
    candidates = [mc for mc in mcs if all(issubclass(mc, other) for other in mcs)]
    if len(candidates) == 1:
        return candidates[0]
    if not candidates:
        raise TypeError("metaclass conflict: no metaclass is a subclass of all others")
    # Multiple equally derived metaclasses – ambiguous
    raise TypeError("metaclass conflict: multiple metaclasses are equally derived")

def popitem(self):
    """Remove and return the `(key, value)` pair least frequently used."""
    if not self:
        raise KeyError('popitem(): dictionary is empty')
    # Find the key with the lowest usage frequency
    try:
        min_key = min(self._freq, key=lambda k: self._freq[k])
    except AttributeError:
        raise AttributeError('popitem requires a _freq attribute tracking usage counts')
    # Remove the key from the dictionary and its frequency counter
    value = self.pop(min_key)
    del self._freq[min_key]
    return (min_key, value)

def popitem(self):
    """Remove and return the `(key, value)` pair least recently used."""
    # Try to use OrderedDict's popitem with last=False if available
    try:
        return super().popitem(last=False)
    except TypeError:
        # Fallback for plain dict or other mapping types
        if isinstance(self, dict):
            if not self:
                raise KeyError('popitem(): dictionary is empty')
            key = next(iter(self))
            return key, self.pop(key)
        # If the object stores its data in an attribute named `_data`
        if hasattr(self, "_data"):
            data = getattr(self, "_data")
            if isinstance(data, dict):
                if not data:
                    raise KeyError('popitem(): dictionary is empty')
                key = next(iter(data))
                return key, data.pop(key)
        # Final fallback: use the items view
        if hasattr(self, "items"):
            items = list(self.items())
            if not items:
                raise KeyError('popitem(): dictionary is empty')
            key, value = items[0]
            del self[key]
            return key, value
        # If none of the above, raise an informative error
        raise TypeError("popitem() not supported for this object")

def popitem(self):
    """Remove and return the `(key, value)` pair most recently used."""
    # Attempt to use OrderedDict's popitem with last=True if available
    try:
        return self.popitem(last=True)
    except TypeError:
        # Fallback for plain dict or other mapping types
        try:
            items = list(self.items())
        except AttributeError:
            raise TypeError(f"{self.__class__.__name__} object has no items() method")
        if not items:
            raise KeyError('popitem(): dictionary is empty')
        key, value = items[-1]
        # Remove the key from the mapping
        del self[key]
        return key, value

def _create_in_regex(self) -> Pattern:
    """Create the in-style parameter regular expression.

    Returns the in-style parameter regular expression (:class:`re.Pattern`).
    """
    try:
        # Matches 'in=' followed by a comma-separated list of non-whitespace tokens,
        # allowing optional spaces around the equals sign and commas.
        pattern = r'\bin\s*=\s*([^\s]+(?:\s*,\s*[^\s]+)*)'
        return re.compile(pattern, re.IGNORECASE)
    except re.error as exc:
        raise ValueError(f"Failed to compile in-style regex: {exc}") from exc

def _create_converter(self) -> _converting._Converter:
    """Create the parameter style converter.

    Returns the parameter style converter (:class:`._converting._Converter`).
    """
    try:
        return _converting._Converter()
    except NameError as exc:
        raise ImportError("Module '_converting' not found") from exc
    except Exception as exc:
        raise RuntimeError("Failed to create parameter style converter") from exc

def fromutc(self, dt):
    """Given a timezone-aware datetime in a given timezone, calculates a
    timezone-aware datetime in a new timezone.

    Since this is the one time that we *know* we have an unambiguous
    datetime object, we take this opportunity to determine whether the
    datetime is ambiguous and in a "fold" state (e.g. if it's the first
    occurrence, chronologically, of the ambiguous datetime).

    :param dt:
        A timezone-aware :class:`datetime.datetime` object.
    """
    # Ensure dt is timezone-aware
    if dt.tzinfo is None:
        raise ValueError("dt must be timezone-aware")
    # If dt is already in the target timezone, just return it
    if dt.tzinfo is self:
        return dt
    # Convert to the target timezone
    try:
        new_dt = dt.astimezone(self)
    except Exception as exc:
        raise ValueError(f"Failed to convert datetime to target timezone: {exc}") from exc
    # Preserve fold information if the target timezone can represent ambiguous times
    # Some tzinfo implementations provide an _is_ambiguous method; use it if available
    if hasattr(self, "_is_ambiguous") and callable(self._is_ambiguous):
        try:
            if self._is_ambiguous(new_dt):
                # If fold is not explicitly set, default to 0 (first occurrence)
                if getattr(new_dt, "fold", 0) == 0:
                    new_dt = new_dt.replace(fold=1)
        except Exception:
            # If _is_ambiguous raises, ignore and return the converted datetime
            pass
    return new_dt

def identify_request(request: RequestType):
    """Try to identify whether this is a Diaspora request.

    Try first public message. Then private message. The check if this is a legacy payload.
    """
    # Validate input
    if request is None:
        return False
    if not isinstance(request, RequestType):
        raise TypeError("request must be an instance of RequestType")

    # Helper to check for a truthy attribute
    def _has_truthy_attr(obj, attr):
        try:
            return bool(getattr(obj, attr, None))
        except Exception:
            return False

    # Check for public message first
    if _has_truthy_attr(request, "public_message"):
        return True

    # Then check for private message
    if _has_truthy_attr(request, "private_message"):
        return True

    # Finally check for legacy payload
    if _has_truthy_attr(request, "legacy_payload"):
        return True

    # If none of the indicators are present, it's not a Diaspora request
    return False

def identify_request(request: RequestType) -> bool:
    """
    Try to identify whether this is a Matrix request
    """
    try:
        # Attempt to get the request path or URL
        path = getattr(request, "path", None)
        if path is None:
            path = getattr(request, "url", None)
        if path is None:
            return False
        # Ensure we are working with a string
        if not isinstance(path, str):
            return False
        # Matrix requests typically start with '/_matrix/' or contain that segment
        return path.startswith("/_matrix/") or "/_matrix/" in path
    except Exception:
        # Any unexpected attribute access or type error results in False
        return False

def format_dt(dt):
    """Format a datetime in the way that D* nodes expect."""
    import datetime
    if dt is None:
        raise ValueError("dt cannot be None")
    if isinstance(dt, datetime.datetime):
        # Format date and time
        date_str = dt.strftime("%Y-%m-%dT%H:%M:%S")
        if dt.tzinfo is not None:
            offset = dt.strftime("%z")
            if offset in ("+0000", "-0000"):
                return f"{date_str}Z"
            # Insert colon into offset (e.g., +02:00)
            offset_formatted = offset[:3] + ":" + offset[3:]
            return f"{date_str}{offset_formatted}"
        return date_str
    if isinstance(dt, datetime.date):
        return dt.strftime("%Y-%m-%d")
    raise TypeError("dt must be a datetime.datetime or datetime.date instance")

def fetch_content_type(url: str) -> Optional[str]:
    """Fetch the HEAD of the remote url to determine the content type."""
    try:
        import urllib.request
        req = urllib.request.Request(url, method='HEAD')
        with urllib.request.urlopen(req, timeout=10) as resp:
            return resp.headers.get('Content-Type')
    except Exception:
        return None

def test_tag(tag: str) -> bool:
    """Test a word whether it could be accepted as a tag."""
    if not isinstance(tag, str):
        return False
    tag = tag.strip()
    if not tag:
        return False
    first = tag[0]
    if not (first.isalpha() or first == '_'):
        return False
    for c in tag[1:]:
        if not (c.isalnum() or c in '._-'):
            return False
    return True

def xml_children_as_dict(node):
    """Turn the children of node <xml> into a dict, keyed by tag name.

    This is only a shallow conversation - child nodes are not recursively processed.
    """
    if node is None:
        return {}
    result = {}
    try:
        for child in node:
            tag = child.tag
            if tag in result:
                existing = result[tag]
                if isinstance(existing, list):
                    existing.append(child)
                else:
                    result[tag] = [existing, child]
            else:
                result[tag] = child
    except TypeError:
        raise TypeError("Provided node is not iterable over children")
    return result

def get_nodeinfo_well_known_document(url, document_path=None):
    """Generate a NodeInfo .well-known document.

    See spec: http://nodeinfo.diaspora.software

    :arg url: The full base url with protocol, ie https://example.com
    :arg document_path: Custom NodeInfo document path if supplied (optional)
    :returns: dict
    """
    # Validate input types
    if not isinstance(url, str) or not url:
        raise TypeError("url must be a non-empty string")
    if document_path is not None and not isinstance(document_path, str):
        raise TypeError("document_path must be a string if provided")

    # Default path if none supplied
    if document_path is None:
        document_path = "/.well-known/nodeinfo"

    # Ensure the path starts with a slash
    if not document_path.startswith("/"):
        document_path = "/" + document_path

    # Build the full href, avoiding duplicate slashes
    base = url.rstrip("/")
    href = base + document_path

    # Construct the .well-known document
    return {
        "links": [
            {
                "rel": "http://nodeinfo.diaspora.software/ns/schema/1.0",
                "href": href
            }
        ]
    }

def verify_relayable_signature(public_key, doc, signature):
    """
    Verify the signed XML elements to have confidence that the claimed
    author did actually generate this message.
    """
    # Basic input validation
    if public_key is None:
        raise ValueError("public_key must not be None")
    if signature is None:
        raise ValueError("signature must not be None")
    if doc is None:
        raise ValueError("doc must not be None")

    # Ensure the public key has a verify method
    if not hasattr(public_key, "verify"):
        raise TypeError("public_key object does not provide a verify method")

    # Prepare the data to be verified
    try:
        if isinstance(doc, str):
            data = doc.encode("utf-8")
        else:
            # Assume doc is already in a suitable binary form
            data = doc
    except Exception as exc:
        raise ValueError(f"Failed to prepare data for verification: {exc}") from exc

    # Attempt verification
    try:
        # The exact signature verification call may vary depending on the
        # cryptographic library in use.  We attempt a generic call that
        # many libraries support.  If the library requires additional
        # parameters (e.g., padding, hash algorithm), the public_key
        # object should handle them internally.
        public_key.verify(signature, data)
        return True
    except Exception:
        # Any exception during verification indicates a failure
        return False

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    if not isinstance(document, str) or not document.strip():
        raise ValueError("document must be a non-empty string")

    # Try JSON first
    try:
        import json
        data = json.loads(document)
        if not isinstance(data, dict):
            raise ValueError("JSON webfinger must be an object")
        result: Dict = {}
        result['subject'] = data.get('subject')
        result['aliases'] = data.get('aliases', [])
        result['links'] = []
        for link in data.get('links', []):
            if isinstance(link, dict):
                result['links'].append({
                    'rel': link.get('rel'),
                    'type': link.get('type'),
                    'href': link.get('href')
                })
        return result
    except Exception:
        # Fallback to XRD (XML) parsing
        try:
            import xml.etree.ElementTree as ET
            root = ET.fromstring(document)
            # Determine namespace if present
            ns = ''
            if root.tag.startswith('{'):
                ns = root.tag.split('}')[0].strip('{')
            ns_map = {'ns': ns} if ns else {}
            def find(tag: str):
                return root.find(f'ns:{tag}' if ns else tag, ns_map)
            def findall(tag: str):
                return root.findall(f'ns:{tag}' if ns else tag, ns_map)

            subject_elem = find('Subject')
            subject = subject_elem.text if subject_elem is not None else None
            aliases = [a.text for a in findall('Alias') if a.text]
            links = []
            for link_elem in findall('Link'):
                rel = link_elem.get('rel')
                type_ = link_elem.get('type')
                href = link_elem.get('href')
                links.append({'rel': rel, 'type': type_, 'href': href})
            return {'subject': subject, 'aliases': aliases, 'links': links}
        except Exception as e:
            raise ValueError("Unable to parse Diaspora webfinger document") from e

def retrieve_and_parse_diaspora_webfinger(handle):
    """Retrieve and parse a remote Diaspora webfinger document.

    :arg handle: Remote handle to retrieve
    :returns: dict
    """
    import urllib.request, urllib.parse, urllib.error, json

    if not isinstance(handle, str) or '@' not in handle:
        raise ValueError("Handle must be a string in the form 'user@domain'")

    user, domain = handle.split('@', 1)
    resource = f'acct:{handle}'
    url = f'https://{domain}/.well-known/webfinger?resource={urllib.parse.quote(resource)}'

    try:
        with urllib.request.urlopen(url, timeout=10) as resp:
            if resp.status != 200:
                raise ValueError(f"HTTP error {resp.status} retrieving webfinger for {handle}")
            data = resp.read().decode('utf-8')
            return json.loads(data)
    except urllib.error.HTTPError as e:
        raise ValueError(f"HTTP error {e.code} retrieving webfinger for {handle}") from e
    except urllib.error.URLError as e:
        raise ValueError(f"URL error retrieving webfinger for {handle}: {e.reason}") from e
    except json.JSONDecodeError as e:
        raise ValueError(f"Failed to parse JSON from webfinger for {handle}") from e

def retrieve_diaspora_host_meta(host):
    """Retrieve a remote Diaspora host-meta document.

    :arg host: Host to retrieve from
    :returns: ``XRD`` instance
    """
    import urllib.request
    import urllib.error
    import urllib.parse

    if not isinstance(host, str) or not host.strip():
        raise ValueError("host must be a non-empty string")

    # Normalize host: strip scheme if present
    parsed = urllib.parse.urlparse(host)
    if parsed.scheme:
        host = parsed.netloc
    else:
        host = host.strip()

    # Build potential URLs to try
    urls = [
        f"https://{host}/.well-known/host-meta",
        f"http://{host}/.well-known/host-meta",
    ]

    for url in urls:
        try:
            with urllib.request.urlopen(url, timeout=10) as resp:
                if resp.status != 200:
                    continue
                data = resp.read()
                try:
                    # Assume XRD has a fromstring classmethod
                    return XRD.fromstring(data)
                except Exception as e:
                    raise ValueError(f"Failed to parse XRD from host-meta at {url}: {e}") from e
        except urllib.error.HTTPError as e:
            # 404 means not found, try next URL
            if e.code == 404:
                continue
            raise
        except urllib.error.URLError:
            # Network error, try next URL
            continue

    raise ValueError(f"Could not retrieve host-meta from host {host}")

def send_document(url, data, timeout=10, method="post", *args, **kwargs):
    """Helper method to send a document via POST.

    Additional ``*args`` and ``**kwargs`` will be passed on to ``requests.post``.

    :arg url: Full url to send to, including protocol
    :arg data: Dictionary (will be form-encoded), bytes, or file-like object to send in the body
    :arg timeout: Seconds to wait for response (defaults to 10)
    :arg method: Method to use, defaults to post
    :returns: Tuple of status code (int or None) and error (exception class instance or None)
    """
    # Validate inputs
    if not isinstance(url, str) or not url:
        raise ValueError("url must be a non-empty string")
    if not isinstance(timeout, (int, float)) or timeout <= 0:
        raise ValueError("timeout must be a positive number")
    if not isinstance(method, str):
        raise ValueError("method must be a string")

    # Prepare request kwargs
    req_kwargs = kwargs.copy()
    req_kwargs['data'] = data
    req_kwargs['timeout'] = timeout

    try:
        # Use requests.request to support any HTTP method
        response = requests.request(method, url, **req_kwargs)
        return (response.status_code, None)
    except Exception as e:
        return (None, e)

def dict_insert(dic, val, key, *keys):
    """insert a value of a nested key into a dictionary

    to insert value for a nested key, all ancestor keys should be given as
    method's arguments

    example:
      dict_insert({}, 'val', 'key1.key2'.split('.'))

    :param dic: a dictionary object to insert the nested key value into
    :param val: a value to insert to the given dictionary
    :param key: first key in a chain of key that will store the value
    :param keys: sub keys in the keys chain
    """
    # Basic validation
    if not isinstance(dic, dict):
        raise TypeError("dic must be a dictionary")
    if key is None:
        raise ValueError("key cannot be None")
    try:
        hash(key)
    except TypeError:
        raise TypeError("key must be hashable")
    for k in keys:
        if k is None:
            raise ValueError("sub keys cannot be None")
        try:
            hash(k)
        except TypeError:
            raise TypeError("sub keys must be hashable")

    # If there are more keys, ensure the current key points to a dict
    if keys:
        if key not in dic:
            dic[key] = {}
        elif not isinstance(dic[key], dict):
            raise TypeError(f"Cannot insert nested key under non-dict key '{key}'")
        # Recurse into the nested dictionary
        return dict_insert(dic[key], val, *keys)
    else:
        # No more keys, set the value
        dic[key] = val
        return dic

def list_of_file_names(settings_dirs, spec_option):
    """Create a new IniType complex type
    """
    import os
    import fnmatch
    # Validate settings_dirs
    if settings_dirs is None:
        raise ValueError("settings_dirs must not be None")
    if isinstance(settings_dirs, str):
        dirs = [settings_dirs]
    else:
        try:
            iter(settings_dirs)
            dirs = list(settings_dirs)
        except TypeError:
            raise TypeError("settings_dirs must be a string or an iterable of directory paths")
    # Validate spec_option
    if spec_option is not None:
        if isinstance(spec_option, str):
            patterns = [spec_option]
        elif isinstance(spec_option, (list, tuple)):
            if not all(isinstance(p, str) for p in spec_option):
                raise TypeError("All elements of spec_option list/tuple must be strings")
            patterns = list(spec_option)
        else:
            raise TypeError("spec_option must be None, a string, or a list/tuple of strings")
    else:
        patterns = None
    result = []
    for d in dirs:
        if not isinstance(d, str):
            continue
        if not os.path.isdir(d):
            continue
        try:
            for entry in os.listdir(d):
                full_path = os.path.join(d, entry)
                if not os.path.isfile(full_path):
                    continue
                if patterns is None:
                    result.append(entry)
                else:
                    if any(fnmatch.fnmatch(entry, pat) for pat in patterns):
                        result.append(entry)
        except (OSError, PermissionError):
            continue
    return result

@classmethod
    def ansible_config_manager(cls):
