@classmethod
    def validate_from_content(cls, spec_content=None):
        """validates that spec (YAML) content has all required fields

        :param spec_content: content of spec file
        :raise IRValidatorException: when mandatory data
        is missing in spec file
        :return: Dictionary with data loaded from a spec (YAML) file
        """
        # Ensure we have something to validate
        if spec_content is None:
            raise IRValidatorException("Spec content is None; cannot validate.")

        # The spec content is expected to be a dictionary (already parsed YAML)
        if not isinstance(spec_content, dict):
            raise IRValidatorException(
                f"Spec content must be a dict, got {type(spec_content).__name__}."
            )

        # Determine required fields; subclasses may define REQUIRED_FIELDS
        required_fields = getattr(cls, "REQUIRED_FIELDS", [])
        if not isinstance(required_fields, (list, tuple)):
            raise IRValidatorException(
                f"REQUIRED_FIELDS must be a list or tuple, got {type(required_fields).__name__}."
            )

        # Find any missing required fields
        missing = [field for field in required_fields if field not in spec_content]
        if missing:
            raise IRValidatorException(
                f"Missing required fields in spec: {', '.join(missing)}."
            )

        # Optionally, check that required fields are not empty
        empty = [
            field
            for field in required_fields
            if not spec_content.get(field)
        ]
        if empty:
            raise IRValidatorException(
                f"Required fields cannot be empty: {', '.join(empty)}."
            )

        return spec_content

@classmethod
    def validate_from_file(cls, yaml_file=None):
        """Loads & validates that a YAML file has all required fields

        :param yaml_file: Path to YAML file
        :raise IRValidatorException: when mandatory data is missing in file
        :return: Dictionary with data loaded from a YAML file
        """
        # Import here to avoid global dependencies
        try:
            import yaml
        except ImportError as exc:
            raise ImportError("PyYAML is required to load YAML files") from exc

        from pathlib import Path

        if yaml_file is None:
            raise ValueError("yaml_file must be provided")

        path = Path(yaml_file)
        if not path.is_file():
            raise FileNotFoundError(f"YAML file not found: {yaml_file}")

        try:
            with path.open("r", encoding="utf-8") as f:
                data = yaml.safe_load(f)
        except yaml.YAMLError as exc:
            raise IRValidatorException(f"Error parsing YAML file {yaml_file}: {exc}") from exc

        if data is None or not isinstance(data, dict):
            raise IRValidatorException(f"YAML file {yaml_file} does not contain a valid dictionary")

        # Determine required fields; subclasses may define REQUIRED_FIELDS
        required = getattr(cls, "REQUIRED_FIELDS", [])
        if required:
            missing = [field for field in required if field not in data]
            if missing:
                raise IRValidatorException(
                    f"Missing required fields in {yaml_file}: {', '.join(missing)}"
                )

        return data

def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files. """
    import os
    import json

    # Helper to merge two dictionaries recursively
    def _merge_dicts(a, b):
        for key, val in b.items():
            if key in a and isinstance(a[key], dict) and isinstance(val, dict):
                a[key] = _merge_dicts(a[key], val)
            else:
                a[key] = val
        return a

    # Recursive processing of includes
    def _process(d, current_path, processed):
        if not isinstance(d, dict):
            return d
        includes = d.pop('include', None)
        if includes is None:
            return d
        if isinstance(includes, str):
            includes = [includes]
        if not isinstance(includes, list):
            raise ValueError(f"Include directive must be a string or list of strings, got {type(includes).__name__}")
        for inc in includes:
            if not isinstance(inc, str):
                raise ValueError(f"Include path must be a string, got {type(inc).__name__}")
            inc_path = os.path.join(os.path.dirname(current_path), inc)
            abs_path = os.path.abspath(inc_path)
            if abs_path in processed:
                continue
            processed.add(abs_path)
            try:
                with open(abs_path, 'r', encoding='utf-8') as f:
                    inc_dict = json.load(f)
            except FileNotFoundError as e:
                raise FileNotFoundError(f"Included file not found: {abs_path}") from e
            except json.JSONDecodeError as e:
                raise ValueError(f"Failed to parse JSON in included file {abs_path}: {e}") from e
            inc_dict = _process(inc_dict, abs_path, processed)
            _merge_dicts(d, inc_dict)
        return d

    # Determine the base path of the current spec file
    base_path = getattr(self, 'spec_path', None) or getattr(self, 'filepath', None) or getattr(self, 'file_path', None) or getattr(self, 'path', None)
    if base_path is None:
        raise ValueError("Cannot resolve includes: no spec_path/filename attribute found on the object.")
    if not isinstance(parser_dict, dict):
        raise TypeError(f"_include_groups expects a dict, got {type(parser_dict).__name__}")
    processed_files = {os.path.abspath(base_path)}
    return _process(parser_dict, base_path, processed_files)

def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources."""
    import os

    # Retrieve the spec dictionary; if missing, return an empty dict
    spec = getattr(self, 'spec', None)
    if spec is None:
        return {}

    # Ensure spec is a dictionary
    if not isinstance(spec, dict):
        raise TypeError(
            f"Expected 'spec' attribute to be a dict, got {type(spec).__name__}"
        )

    # Retrieve defaults if available; ignore if not a dict
    defaults = getattr(self, 'defaults', {})
    if not isinstance(defaults, dict):
        defaults = {}

    resolved = {}
    for key, value in spec.items():
        if value is None:
            # 1. Try the defaults dictionary
            if key in defaults:
                resolved[key] = defaults[key]
                continue

            # 2. Try an environment variable (uppercased key)
            env_val = os.getenv(key.upper())
            if env_val is not None:
                resolved[key] = env_val
                continue

            # 3. Leave as None if nothing found
            resolved[key] = None
        else:
            resolved[key] = value

    return resolved

def get_deprecated_args(self):
    """Returning dict with options which deprecate others."""
    # Default implementation returns an empty mapping.
