def validate_arg_deprecation(self, cli_args, answer_file_args):
    """Validates and prints the deprecated arguments.

    :param cli_args: the dict of arguments from cli
    :param answer_file_args:  the dict of arguments from files
    """
    # Ensure inputs are dictionaries (allow None as empty)
    if cli_args is None:
        cli_args = {}
    if answer_file_args is None:
        answer_file_args = {}
    if not isinstance(cli_args, dict):
        raise TypeError("cli_args must be a dict")
    if not isinstance(answer_file_args, dict):
        raise TypeError("answer_file_args must be a dict")

    # Retrieve deprecated arguments mapping from the instance
    deprecated = getattr(self, "deprecated_args", None)
    if not deprecated:
        return  # nothing to validate

    # Normalise deprecated mapping to a dict: {old_name: new_name or None}
    if isinstance(deprecated, (list, set, tuple)):
        deprecated_map = {arg: None for arg in deprecated}
    elif isinstance(deprecated, dict):
        deprecated_map = deprecated
    else:
        raise TypeError("deprecated_args must be a dict or an iterable of strings")

    # Helper to format warning messages
    def _warn(arg, new):
        if new:
            print(f"Warning: Argument '{arg}' is deprecated. Use '{new}' instead.")
        else:
            print(f"Warning: Argument '{arg}' is deprecated and will be removed in future.")

    # Check CLI arguments
    for arg in cli_args:
        if arg in deprecated_map:
            _warn(arg, deprecated_map[arg])

    # Check answer file arguments
    for arg in answer_file_args:
        if arg in deprecated_map:
            _warn(arg, deprecated_map[arg])

def get_parser_option_specs(self, command_name):
    """Gets all the options for the specified command

    :param command_name: the command name (main, virsh, ospd, etc...)
    :return: the list of all command options
    """
    # Validate input
    if not isinstance(command_name, str):
        raise TypeError("command_name must be a string")
    if not command_name.strip():
        raise ValueError("command_name cannot be empty or whitespace")

    # Normalise command name (case‑insensitive lookup)
    key = command_name.strip().lower()

    # Ensure the object has a mapping of command options
    if not hasattr(self, "_command_options"):
        raise AttributeError("The object does not contain a '_command_options' attribute")

    # Retrieve the options for the requested command
    try:
        options = self._command_options[key]
    except KeyError:
        raise ValueError(f"No options found for command '{command_name}'")

    # Ensure the returned value is iterable
    if options is None:
        return []
    if not hasattr(options, "__iter__"):
        raise TypeError(f"Options for command '{command_name}' are not iterable")

    # Return a shallow copy to prevent accidental mutation
    return list(options)

def get_silent_args(self, args):
    """list of silenced argument

    :param args: The received arguments.
    :return: list, slienced argument names
    """
    silent = []
    if args is None:
        return silent

    # If args is a mapping (e.g., dict), check each key/value pair
    if isinstance(args, dict):
        for key, value in args.items():
            if value is None or value == '':
                silent.append(key)

    # If args is a sequence of (name, value) pairs
    elif isinstance(args, (list, tuple)):
        for item in args:
            if isinstance(item, (list, tuple)) and len(item) == 2:
                name, value = item
                if value is None or value == '':
                    silent.append(name)
            else:
                # If the item is just a name, treat it as silent
                silent.append(item)

    # For any other type, return an empty list
    return silent

def validate_requires_args(self, args):
    """Check if all the required arguments have been provided. """
    # Ensure args is a mapping
    if args is None:
        raise TypeError("args cannot be None")
    if not isinstance(args, dict):
        raise TypeError(f"args must be a dict, got {type(args).__name__}")

    # Retrieve the list of required argument names
    required = getattr(self, "REQUIRED_ARGS", [])
    if required is None:
        required = []

    # Ensure required is iterable
    try:
        iter(required)
    except TypeError:
        raise TypeError(f"REQUIRED_ARGS must be an iterable, got {type(required).__name__}")

    # Find missing arguments
    missing = [name for name in required if name not in args or args[name] is None]

    if missing:
        missing_str = ", ".join(missing)
        raise ValueError(f"Missing required arguments: {missing_str}")

    return True

def _get_conditionally_required_args(self, command_name, options_spec, args):
    """List arguments with ``required_when`` condition matched.

    :param command_name: the command name.
    :param options_spec:  the list of command spec options.
    :param args: the received input arguments
    :return: list, list of argument names with matched ``required_when``
        condition
    """
    required = []
    if not options_spec:
        return required
    # Ensure args is a dict for evaluation
    if args is None:
        args = {}
    for opt in options_spec:
        # Retrieve option name
        name = None
        if isinstance(opt, dict):
            name = opt.get('name')
            cond = opt.get('required_when')
        else:
            name = getattr(opt, 'name', None)
            cond = getattr(opt, 'required_when', None)
        if not name or cond is None:
            continue
        try:
            if callable(cond):
                matched = bool(cond(args))
            else:
                # Treat cond as a string expression
                matched = bool(eval(cond, {}, args))
        except Exception:
            matched = False
        if matched:
            required.append(name)
    return required

def validate_length_args(self, args):
    """Check if value of arguments is not longer than length specified.

    :param args: The received arguments.
    """
    # Retrieve the mapping of argument names or positions to maximum lengths.
    max_lengths = getattr(self, "_max_lengths", None)

    # If no length constraints are defined, nothing to validate.
    if max_lengths is None:
        return True

    # Helper to validate a single value against a maximum length.
    def _check_value(name, value, max_len):
        if value is None:
            return
        try:
            length = len(value)
        except TypeError:
            # Value has no length; skip validation for this type.
            return
        if length > max_len:
            raise ValueError(
                f"Argument '{name}' length {length} exceeds maximum allowed {max_len}."
            )

    # Validate when args is a mapping (dict-like).
    if isinstance(args, dict):
        if not isinstance(max_lengths, dict):
            raise TypeError(
                "When args is a dict, _max_lengths must be a dict mapping argument names to maximum lengths."
            )
        for key, value in args.items():
            max_len = max_lengths.get(key)
            if max_len is None:
                continue
            _check_value(key, value, max_len)

    # Validate when args is a sequence (list or tuple).
    elif isinstance(args, (list, tuple)):
        if not isinstance(max_lengths, (list, tuple)):
            raise TypeError(
                "When args is a list or tuple, _max_lengths must be a list or tuple of maximum lengths."
            )
        seq = list(args)
        for idx, value in enumerate(seq):
            if idx >= len(max_lengths):
                # No constraint defined for this position; skip.
                break
            max_len = max_lengths[idx]
            if max_len is None:
                continue
            _check_value(idx, value, max_len)

    else:
        raise TypeError("args must be a dict, list, or tuple.")

    return True

def validate_choices_args(self, args):
    """Check if value of choice arguments is one of the available choices.

    :param args: The received arguments.
    """
    # Ensure args is a mapping of argument names to values
    if not isinstance(args, dict):
        raise TypeError("args must be a dictionary of argument names to values")

    # The object must provide a mapping of argument names to allowed choices
    if not hasattr(self, "choices") or not isinstance(self.choices, dict):
        raise AttributeError("Object does not have a 'choices' dictionary to validate against")

    # Iterate over the provided arguments and validate each choice
    for name, value in args.items():
        if name in self.choices:
            allowed = self.choices[name]
            # If the allowed set is empty or None, skip validation
            if not allowed:
                continue
            try:
                if value not in allowed:
                    raise ValueError(
                        f"Invalid value for argument '{name}': {value!r}. "
                        f"Allowed choices are: {allowed}"
                    )
            except TypeError:
                # In case allowed is not a proper iterable
                raise TypeError(
                    f"Allowed choices for argument '{name}' must be an iterable"
                ) from None

    return True

def validate_min_max_args(self, args):
    """Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments.
    """
    # Ensure the object has min and max attributes
    if not hasattr(self, 'min') or not hasattr(self, 'max'):
        raise AttributeError("Object must have 'min' and 'max' attributes for validation.")
    min_val = getattr(self, 'min')
    max_val = getattr(self, 'max')

    # Validate that min and max are numeric
    if not isinstance(min_val, (int, float)) or not isinstance(max_val, (int, float)):
        raise TypeError("Both 'min' and 'max' attributes must be numeric.")
    if min_val > max_val:
        raise ValueError(f"Invalid bounds: min ({min_val}) is greater than max ({max_val}).")

    # Determine how to iterate over args
    if isinstance(args, dict):
        iterable = args.items()
    elif isinstance(args, (list, tuple)):
        iterable = enumerate(args)
    else:
        raise TypeError("args must be a dict, list, or tuple.")

    for key, value in iterable:
        # Skip None values
        if value is None:
            continue
        # Ensure the value is numeric
        if not isinstance(value, (int, float)):
            raise TypeError(f"Argument '{key}' value must be numeric, got {type(value).__name__}.")
        # Check bounds
        if value < min_val or value > max_val:
            raise ValueError(f"Argument '{key}' value {value} out of bounds [{min_val}, {max_val}].")

    return True

def create_complex_argumet_type(self, subcommand, type_name, option_name,
                                    spec_option):
    """Build the complex argument type

    :param subcommand: the command name
    :param type_name: the complex type name
    :param option_name: the option name
    :param spec_option: option's specifications
    :return: the complex type instance
    """
    # Basic type validation
    if not isinstance(subcommand, str):
        raise TypeError("subcommand must be a string")
    if not isinstance(type_name, str):
        raise TypeError("type_name must be a string")
    if not isinstance(option_name, str):
        raise TypeError("option_name must be a string")
    if not isinstance(spec_option, dict):
        raise TypeError("spec_option must be a dictionary")

    try:
        # Attempt to create a proper ComplexArgumentType instance if available
        complex_type = ComplexArgumentType(
            subcommand=subcommand,
            type_name=type_name,
            option_name=option_name,
            **spec_option
        )
    except Exception as exc:
        # Fallback to a simple dictionary representation if the class is not defined
        complex_type = {
            'subcommand': subcommand,
            'type_name': type_name,
            'option_name': option_name,
            'spec_option': spec_option
        }
        # If the exception was not a NameError, re‑raise it as a ValueError
        if not isinstance(exc, NameError):
            raise ValueError(
                f"Failed to create complex argument type for option '{option_name}': {exc}"
            ) from exc

    return complex_type

def get_nested_custom_and_control_args(self, args):
    """Split input arguments to control nested and custom.

    Controls arguments: control the IR behavior. These arguments
        will not be put into the spec yml file
    Nested arguments: are used by the Ansible playbooks and will be put
        into the spec yml file.
    Custom arguments: Custom ansible variables to be used instead of the
        normal nested usage.

    :param args: the collected list of args.
    :return: (dict, dict): flat dicts (control_args, nested_args)
    """
    control_args = {}
    nested_args = {}

    # Helper to process a key/value pair
    def _add_pair(key, value):
        if not isinstance(key, str):
            return
        # Define control keys: underscore prefix or common control names
        control_keys = {
            'debug', 'verbose', 'check_mode', 'force',
            'force_update', 'force_install', 'dry_run', 'async',
            'poll', 'timeout', 'register', 'ignore_errors'
        }
        if key.startswith('_') or key in control_keys:
            control_args[key] = value
        else:
            nested_args[key] = value

    # If args is None, return empty dicts
    if args is None:
        return control_args, nested_args

    # If args is a dict, iterate items
    if isinstance(args, dict):
        for k, v in args.items():
            _add_pair(k, v)
    # If args is a list or tuple, it may contain dicts or key/value pairs
    elif isinstance(args, (list, tuple)):
        for item in args:
            if isinstance(item, dict):
                for k, v in item.items():
                    _add_pair(k, v)
            elif isinstance(item, (list, tuple)) and len(item) == 2:
                k, v = item
                _add_pair(k, v)
            else:
                # Unsupported item type; ignore
                continue
    else:
        # Unsupported args type; ignore
        pass

    return control_args, nested_args

@staticmethod
    def merge_extra_vars(vars_dict, extra_vars=None):
        """Extend ``vars_dict`` with ``extra-vars``

        :param vars_dict: Dictionary to merge extra-vars into
        :param extra_vars: List of extra-vars
        """
        if not isinstance(vars_dict, dict):
            raise TypeError("vars_dict must be a dict")
        if not extra_vars:
            return vars_dict

        # If a dict is provided, update directly
        if isinstance(extra_vars, dict):
            vars_dict.update(extra_vars)
            return vars_dict

        # Accept any iterable of items (list, tuple, set, etc.)
        try:
            iterator = iter(extra_vars)
        except TypeError:
            raise TypeError("extra_vars must be a dict or an iterable of key/value pairs")

        for item in iterator:
            if isinstance(item, dict):
                vars_dict.update(item)
            elif isinstance(item, (list, tuple)) and len(item) == 2:
                key, value = item
                vars_dict[key] = value
            elif isinstance(item, str):
                if '=' in item:
                    key, value = item.split('=', 1)
                    vars_dict[key] = value
                else:
                    raise ValueError(f"Invalid extra var string: {item!r}")
            else:
                raise ValueError(f"Unsupported extra var type: {type(item).__name__}")

        return vars_dict

def ansible_playbook(ir_workspace, ir_plugin, playbook_path, verbose=None,
                     extra_vars=None, ansible_args=None):
    """Wraps the 'ansible-playbook' CLI.

     :param ir_workspace: An Infrared Workspace object represents the active
     workspace
     :param ir_plugin: An InfraredPlugin object of the current plugin
     :param playbook_path: the playbook to invoke
     :param verbose: Ansible verbosity level
     :param extra_vars: dict. Passed to Ansible as extra-vars
     :param ansible_args: dict of ansible-playbook arguments to plumb down
         directly to Ansible.
    """
    # Basic type validation
    if not isinstance(playbook_path, str):
        raise TypeError("playbook_path must be a string")
    if extra_vars is not None and not isinstance(extra_vars, dict):
        raise TypeError("extra_vars must be a dict")
    if ansible_args is not None and not isinstance(ansible_args, dict):
        raise TypeError("ansible_args must be a dict")

    # Build the command list
    cmd = ['ansible-playbook', playbook_path]

    # Handle verbosity
    if verbose:
        if isinstance(verbose, int) and verbose > 0:
            cmd.append('-' + 'v' * verbose)
        elif isinstance(verbose, bool) and verbose:
            cmd.append('-v')
        elif isinstance(verbose, str):
            cmd.append(verbose)

    # Handle ansible_args
    if ansible_args:
        for key, value in ansible_args.items():
            if not isinstance(key, str):
                continue
            if value is True:
                cmd.append(key)
            elif value is False or value is None:
                continue
            else:
                cmd.append(key)
                cmd.append(str(value))

    # Handle extra_vars
    if extra_vars:
        # Import json locally to avoid module-level imports
        import json
        json_str = json.dumps(extra_vars)
        cmd.extend(['--extra-vars', json_str])

    # Execute the command
    try:
        result = subprocess.run(
            cmd,
            capture_output=True,
            text=True,
            check=False
        )
    except FileNotFoundError as e:
        raise RuntimeError("ansible-playbook command not found") from e
    except Exception as e:
        raise RuntimeError(f"Error running ansible-playbook: {e}") from e

    # Raise an error if the command failed
    if result.returncode != 0:
        raise RuntimeError(
            f"ansible-playbook failed with exit code {result.returncode}\n"
            f"stdout: {result.stdout}\n"
            f"stderr: {result.stderr}"
        )

    return result

def _convert_non_cli_args(self, parser_name, values_dict):
    """Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of with arguments
    """
    if not isinstance(values_dict, dict):
        raise TypeError("values_dict must be a dict")

    for key, val in list(values_dict.items()):
        # Skip if value is already a non-string type
        if val is None or isinstance(val, (int, float, bool)):
            continue
        if not isinstance(val, str):
            continue

        s = val.strip()

        # Boolean conversion
        if s.lower() == "true":
            values_dict[key] = True
            continue
        if s.lower() == "false":
            values_dict[key] = False
            continue

        # None conversion
        if s.lower() == "none":
            values_dict[key] = None
            continue

        # Integer conversion
        if s.isdigit() or (s.startswith("-") and s[1:].isdigit()):
            try:
                values_dict[key] = int(s)
                continue
            except ValueError:
                pass

        # Float conversion
        try:
            f = float(s)
            # Only keep as float if the string actually represents a float
            if "." in s or "e" in s.lower():
                values_dict[key] = f
                continue
        except ValueError:
            pass

        # List conversion (comma separated)
        if "," in s:
            parts = [p.strip() for p in s.split(",")]
            casted = []
            for p in parts:
                # Reuse the same conversion logic for each part
                if p.lower() == "true":
                    casted.append(True)
                elif p.lower() == "false":
                    casted.append(False)
                elif p.lower() == "none":
                    casted.append(None)
                elif p.isdigit() or (p.startswith("-") and p[1:].isdigit()):
                    try:
                        casted.append(int(p))
                    except ValueError:
                        casted.append(p)
                else:
                    try:
                        fp = float(p)
                        if "." in p or "e" in p.lower():
                            casted.append(fp)
                        else:
                            casted.append(p)
                    except ValueError:
                        casted.append(p)
            values_dict[key] = casted
            continue

        # Default: keep trimmed string
        values_dict[key] = s
    # No explicit return needed; values_dict is modified in place.

def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    import os
    import json

    # Helper to flatten nested dictionaries
    def _flatten(d, parent_key='', sep='.'):
        items = {}
        for k, v in d.items():
            new_key = f"{parent_key}{sep}{k}" if parent_key else k
            if isinstance(v, dict):
                items.update(_flatten(v, new_key, sep=sep))
            elif isinstance(v, list):
                # Flatten list items with index
                for idx, item in enumerate(v):
                    list_key = f"{new_key}{sep}{idx}"
                    if isinstance(item, dict):
                        items.update(_flatten(item, list_key, sep=sep))
                    else:
                        items[list_key] = item
            else:
                items[new_key] = v
        return items

    # Validate plugin_dir
    if not plugin_dir:
        raise ValueError("plugin_dir must be a non-empty path")
    if not os.path.isdir(plugin_dir):
        raise FileNotFoundError(f"Plugin directory not found: {plugin_dir}")

    # Determine spec file: prefer JSON, fallback to YAML
    spec_file = None
    json_path = os.path.join(plugin_dir, "plugin.json")
    yaml_path = os.path.join(plugin_dir, "plugin.yaml")
    if os.path.isfile(json_path):
        spec_file = json_path
        parser = json.load
    elif os.path.isfile(yaml_path):
        try:
            import yaml
        except ImportError:
            raise ImportError("YAML support required to parse plugin.yaml")
        spec_file = yaml_path
        parser = yaml.safe_load
    else:
        raise FileNotFoundError("No plugin spec file found in directory")

    # Read and parse spec
    try:
        with open(spec_file, "r", encoding="utf-8") as f:
            data = parser(f)
    except Exception as exc:
        raise ValueError(f"Failed to parse plugin spec: {exc}") from exc

    if not isinstance(data, dict):
        raise ValueError("Plugin spec must be a dictionary at the top level")

    # Flatten and return
    return _flatten(data)

def inject_config(self):
    """Set the environment variable for config path, if it is undefined."""
    import os
    env_var = 'CONFIG_PATH'
    # Only set if not already defined or empty
    if not os.environ.get(env_var):
        # Determine a sensible default path
        try:
            base_dir = os.path.dirname(__file__)
        except NameError:
            base_dir = os.getcwd()
        default_path = os.path.join(base_dir, 'config.json')
        try:
            os.environ[env_var] = default_path
        except Exception:
            # If setting the environment variable fails, silently ignore
            pass
